// Minimal terminal UI toolkit: screen, pixels, colors.
#pragma once
#include <cstdint>
#include <string>
#include <vector>

namespace tui {

enum class ColorSupport { Palette16 = 1, Palette256 = 2, TrueColor = 3 };
ColorSupport TerminalColorSupport();
void SetTerminalColorSupport(ColorSupport c);

class Color {
 public:
  enum Type : uint8_t { Default, P16, P256, RGB };
  Color() = default;
  static Color Index16(int i);
  static Color Index256(int i);
  static Color Rgb(int r, int g, int b);
  static Color DefaultColor() { return Color(); }

  std::string Print(bool background) const;
  bool operator==(const Color& o) const {
    return type_ == o.type_ && r_ == o.r_ && g_ == o.g_ && b_ == o.b_;
  }
  bool operator!=(const Color& o) const { return !(*this == o); }
  Type type() const { return type_; }

  // Palette 16 names.
  static Color Black() { return Index16(0); }
  static Color Red() { return Index16(1); }
  static Color Green() { return Index16(2); }
  static Color Yellow() { return Index16(3); }
  static Color Blue() { return Index16(4); }
  static Color Magenta() { return Index16(5); }
  static Color Cyan() { return Index16(6); }
  static Color GrayLight() { return Index16(7); }
  static Color GrayDark() { return Index16(8); }
  static Color RedLight() { return Index16(9); }
  static Color GreenLight() { return Index16(10); }
  static Color YellowLight() { return Index16(11); }
  static Color BlueLight() { return Index16(12); }
  static Color MagentaLight() { return Index16(13); }
  static Color CyanLight() { return Index16(14); }
  static Color White() { return Index16(15); }

 private:
  Type type_ = Default;
  uint8_t r_ = 0, g_ = 0, b_ = 0;
};

struct Pixel {
  bool blink = false;
  bool bold = false;
  bool dim = false;
  bool italic = false;
  bool inverted = false;
  bool underlined = false;
  bool underlined_double = false;
  bool strikethrough = false;
  bool automerge = false;
  Color background_color;
  Color foreground_color;
  std::string character = " ";
};

struct Box {
  int x_min = 0;
  int x_max = 0;
  int y_min = 0;
  int y_max = 0;
  static Box Intersection(Box a, Box b) {
    return Box{std::max(a.x_min, b.x_min), std::min(a.x_max, b.x_max),
               std::max(a.y_min, b.y_min), std::min(a.y_max, b.y_max)};
  }
  static Box Union(Box a, Box b) {
    return Box{std::min(a.x_min, b.x_min), std::max(a.x_max, b.x_max),
               std::min(a.y_min, b.y_min), std::max(a.y_max, b.y_max)};
  }
  bool Contain(int x, int y) const {
    return x_min <= x && x_max >= x && y_min <= y && y_max >= y;
  }
  bool IsEmpty() const { return x_min > x_max || y_min > y_max; }
  bool operator==(const Box& o) const {
    return x_min == o.x_min && x_max == o.x_max && y_min == o.y_min &&
           y_max == o.y_max;
  }
  bool operator!=(const Box& o) const { return !(*this == o); }
};

class Screen {
 public:
  Screen(int dimx, int dimy);
  Pixel& PixelAt(int x, int y);
  std::string& at(int x, int y) { return PixelAt(x, y).character; }
  int dimx() const { return dimx_; }
  int dimy() const { return dimy_; }
  std::string ToString() const;
  std::string ResetPosition(bool clear) const;
  void Clear();
  void ApplyShader();

  struct Cursor {
    int x = 0;
