ColorSupport ComputeColorSupport() {
  const char* ct = std::getenv("COLORTERM");
  std::string colorterm = ct ? ct : "";
  if (Contains(colorterm, "24bit") || Contains(colorterm, "truecolor")) {
    return ColorSupport::TrueColor;
  }
  const char* t = std::getenv("TERM");
  std::string term = t ? t : "";
  if (Contains(colorterm, "256") || Contains(term, "256")) {
    return ColorSupport::Palette256;
  }
  return ColorSupport::Palette16;
}
}  // namespace

ColorSupport TerminalColorSupport() {
  if (!g_color_support_init) {
    g_color_support = ComputeColorSupport();
    g_color_support_init = true;
  }
  return g_color_support;
}

void SetTerminalColorSupport(ColorSupport c) {
  g_color_support = c;
  g_color_support_init = true;
}

Color Color::Index16(int i) {
  Color c;
  c.type_ = P16;
  c.r_ = static_cast<uint8_t>(i);
  return c;
}

Color Color::Index256(int i) {
  Color c;
  c.type_ = P256;
  c.r_ = static_cast<uint8_t>(i);
  if (TerminalColorSupport() >= ColorSupport::Palette256) {
    return c;
  }
  c.type_ = P16;
  c.r_ = static_cast<uint8_t>(kColorTable[i].index16);
  return c;
}

Color Color::Rgb(int r, int g, int b) {
  Color c;
  c.type_ = RGB;
  c.r_ = static_cast<uint8_t>(r);
  c.g_ = static_cast<uint8_t>(g);
  c.b_ = static_cast<uint8_t>(b);
  if (TerminalColorSupport() == ColorSupport::TrueColor) {
    return c;
  }
  int closest = 256 * 256 * 3;
  int best = 0;
  for (int i = 16; i < 256; ++i) {
    const int dr = kColorTable[i].r - r;
    const int dg = kColorTable[i].g - g;
    const int db = kColorTable[i].b - b;
    const int dist = dr * dr + dg * dg + db * db;
    if (closest > dist) {
      closest = dist;
      best = i;
    }
  }
  Color o;
  if (TerminalColorSupport() == ColorSupport::Palette256) {
    o.type_ = P256;
    o.r_ = static_cast<uint8_t>(best);
  } else {
    o.type_ = P16;
    o.r_ = static_cast<uint8_t>(kColorTable[best].index16);
  }
  return o;
}

std::string Color::Print(bool background) const {
  switch (type_) {
    case Default:
      return background ? "49" : "39";
    case P16: {
      int base = r_ < 8 ? (background ? 40 : 30) : (background ? 100 : 90);
      return std::to_string(base + (r_ % 8));
    }
    case P256:
      return (background ? "48;5;" : "38;5;") + std::to_string(r_);
    case RGB:
      return (background ? "48;2;" : "38;2;") + std::to_string(r_) + ";" +
             std::to_string(g_) + ";" + std::to_string(b_);
  }
  return "";
}

