    ss << (((prev.bold && !next.bold) || (prev.dim && !next.dim)) ? "\x1B[22m"
                                                                   : "");
    ss << (next.bold ? "\x1B[1m" : "");
    ss << (next.dim ? "\x1B[2m" : "");
