void UpgradeLeftRight(std::string& left, std::string& right) {
  const auto& enc = TileEncoding();
  const auto& inv = TileInverse();
  auto il = enc.find(left);
  if (il == enc.end()) return;
  auto ir = enc.find(right);
  if (ir == enc.end()) return;
  const Tile tl = il->second;
  const Tile tr = ir->second;
  if (tl.right == 0 && tr.left != 0) {
    Tile e = tl;
    e.right = tr.left;
    auto u = inv.find(e);
    if (u != inv.end()) left = u->second;
  }
  if (tr.left == 0 && tl.right != 0) {
    Tile e = tr;
    e.left = tl.right;
    auto u = inv.find(e);
    if (u != inv.end()) right = u->second;
  }
}

void UpgradeTopDown(std::string& top, std::string& down) {
  const auto& enc = TileEncoding();
  const auto& inv = TileInverse();
  auto it = enc.find(top);
  if (it == enc.end()) return;
  auto id = enc.find(down);
  if (id == enc.end()) return;
  const Tile tt = it->second;
  const Tile td = id->second;
  if (tt.down == 0 && td.top != 0) {
    Tile e = tt;
    e.down = td.top;
    auto u = inv.find(e);
    if (u != inv.end()) top = u->second;
