  if ((C0 & 0xF0) == 0xE0 && start + 2 < input.size()) {
    uint8_t C1 = input[start + 1];
    uint8_t C2 = input[start + 2];
    *end = start + 3;
    *ucs = ((C0 & 0x0F) << 12) | ((C1 & 0x3F) << 6) | (C2 & 0x3F);
    return true;
