bool IsCombining(uint32_t c) {
  return InTable(c, kCombining, sizeof(kCombining) / sizeof(kCombining[0]));
}
bool IsFullWidth(uint32_t c) {
  if (c < 0x0300) return false;
  return InTable(c, kFullWidth, sizeof(kFullWidth) / sizeof(kFullWidth[0]));
}
bool IsControl(uint32_t c) {
  if (c == 0) return true;
  if (c < 32) return true;
  if (c >= 0x7f && c < 0xa0) return true;
  return false;
}
}  // namespace

std::vector<std::string> Utf8ToGlyphs(const std::string& input) {
  std::vector<std::string> out;
  out.reserve(input.size());
  size_t start = 0;
  size_t end = 0;
  while (start < input.size()) {
    uint32_t cp = 0;
    if (!EatCodePoint(input, start, &end, &cp)) {
      start = end;
      continue;
    }
    std::string append = input.substr(start, end - start);
    start = end;
    if (IsControl(cp)) continue;
    if (IsCombining(cp)) {
      if (!out.empty()) out.back() += append;
      continue;
    }
    if (IsFullWidth(cp)) {
      out.push_back(append);
      out.emplace_back("");
      continue;
    }
    out.push_back(append);
  }
  return out;
}

int StringWidth(const std::string& input) {
  int width = 0;
  size_t start = 0;
  while (start < input.size()) {
    uint32_t cp = 0;
    size_t end = 0;
    if (!EatCodePoint(input, start, &end, &cp)) {
      start = end;
      continue;
    }
    start = end;
    if (IsControl(cp)) continue;
    if (IsCombining(cp)) continue;
    if (IsFullWidth(cp)) {
      width += 2;
      continue;
    }
    width += 1;
  }
  return width;
}

std::wstring Utf8ToWide(const std::string& s) {
  std::wstring out;
  size_t start = 0;
  while (start < s.size()) {
    uint32_t cp = 0;
    size_t end = 0;
    if (!EatCodePoint(s, start, &end, &cp)) {
      start = end;
      continue;
    }
    start = end;
    out.push_back(static_cast<wchar_t>(cp));
  }
  return out;
}

std::string WideToUtf8(const std::wstring& s) {
  std::string out;
  for (wchar_t wc : s) {
    uint32_t c = static_cast<uint32_t>(wc);
    if (c < 0x80) {
      out.push_back(static_cast<char>(c));
    } else if (c < 0x800) {
      out.push_back(static_cast<char>(0xC0 | (c >> 6)));
      out.push_back(static_cast<char>(0x80 | (c & 0x3F)));
    } else if (c < 0x10000) {
      out.push_back(static_cast<char>(0xE0 | (c >> 12)));
      out.push_back(static_cast<char>(0x80 | ((c >> 6) & 0x3F)));
      out.push_back(static_cast<char>(0x80 | (c & 0x3F)));
    } else {
      out.push_back(static_cast<char>(0xF0 | (c >> 18)));
      out.push_back(static_cast<char>(0x80 | ((c >> 12) & 0x3F)));
      out.push_back(static_cast<char>(0x80 | ((c >> 6) & 0x3F)));
      out.push_back(static_cast<char>(0x80 | (c & 0x3F)));
    }
  }
  return out;
}

