namespace {
ColorSupport g_color_support = ColorSupport::Palette16;
bool g_color_support_init = false;

bool Contains(const std::string& s, const char* k) {
  return s.find(k) != std::string::npos;
}

ColorSupport ComputeColorSupport() {
  const char* ct = std::getenv("COLORTERM");
  std::string colorterm = ct ? ct : "";
  if (Contains(colorterm, "24bit") || Contains(colorterm, "truecolor")) {
    return ColorSupport::TrueColor;
  }
  const char* t = std::getenv("TERM");
  std::string term = t ? t : "";
  if (Contains(colorterm, "256") || Contains(term, "256")) {
    return ColorSupport::Palette256;
  }
  return ColorSupport::Palette16;
}
}  // namespace

ColorSupport TerminalColorSupport() {
  if (!g_color_support_init) {
    g_color_support = ComputeColorSupport();
    g_color_support_init = true;
  }
  return g_color_support;
}

void SetTerminalColorSupport(ColorSupport c) {
  g_color_support = c;
  g_color_support_init = true;
}

Color Color::Index16(int i) {
  Color c;
  c.type_ = P16;
  c.r_ = static_cast<uint8_t>(i);
  return c;
}

Color Color::Index256(int i) {
  Color c;
  c.type_ = P256;
  c.r_ = static_cast<uint8_t>(i);
  if (TerminalColorSupport() >= ColorSupport::Palette256) {
    return c;
  }
  c.type_ = P16;
  c.r_ = static_cast<uint8_t>(kColorTable[i].index16);
  return c;
}

Color Color::Rgb(int r, int g, int b) {
  Color c;
  c.type_ = RGB;
  c.r_ = static_cast<uint8_t>(r);
  c.g_ = static_cast<uint8_t>(g);
  c.b_ = static_cast<uint8_t>(b);
  if (TerminalColorSupport() == ColorSupport::TrueColor) {
    return c;
  }
  int closest = 256 * 256 * 3;
  int best = 0;
  for (int i = 16; i < 256; ++i) {
    const int dr = kColorTable[i].r - r;
    const int dg = kColorTable[i].g - g;
    const int db = kColorTable[i].b - b;
    const int dist = dr * dr + dg * dg + db * db;
    if (closest > dist) {
      closest = dist;
      best = i;
    }
  }
  Color o;
  if (TerminalColorSupport() == ColorSupport::Palette256) {
    o.type_ = P256;
    o.r_ = static_cast<uint8_t>(best);
  } else {
    o.type_ = P16;
    o.r_ = static_cast<uint8_t>(kColorTable[best].index16);
  }
  return o;
}

std::string Color::Print(bool background) const {
  switch (type_) {
    case Default:
      return background ? "49" : "39";
    case P16: {
      int base = r_ < 8 ? (background ? 40 : 30) : (background ? 100 : 90);
      return std::to_string(base + (r_ % 8));
    }
    case P256:
      return (background ? "48;5;" : "38;5;") + std::to_string(r_);
    case RGB:
      return (background ? "48;2;" : "38;2;") + std::to_string(r_) + ";" +
             std::to_string(g_) + ";" + std::to_string(b_);
  }
  return "";
}

Screen::Screen(int dimx, int dimy)
    : stencil{0, dimx - 1, 0, dimy - 1},
      dimx_(dimx),
      dimy_(dimy),
      pixels_(dimy, std::vector<Pixel>(dimx)) {}

Pixel& Screen::PixelAt(int x, int y) {
  if (stencil.Contain(x, y) && x >= 0 && y >= 0 && x < dimx_ && y < dimy_) {
    return pixels_[y][x];
  }
  dev_null_ = Pixel();
  return dev_null_;
}

namespace {
void UpdatePixelStyle(std::stringstream& ss, const Pixel& prev,
                      const Pixel& next) {
  if ((next.bold != prev.bold) || (next.dim != prev.dim)) {
    ss << (((prev.bold && !next.bold) || (prev.dim && !next.dim)) ? "\x1B[22m"
                                                                   : "");
    ss << (next.bold ? "\x1B[1m" : "");
    ss << (next.dim ? "\x1B[2m" : "");
  }
  if (next.underlined != prev.underlined ||
      next.underlined_double != prev.underlined_double) {
    ss << (next.underlined          ? "\x1B[4m"
           : next.underlined_double ? "\x1B[21m"
                                    : "\x1B[24m");
  }
  if (next.blink != prev.blink) {
    ss << (next.blink ? "\x1B[5m" : "\x1B[25m");
  }
  if (next.inverted != prev.inverted) {
    ss << (next.inverted ? "\x1B[7m" : "\x1B[27m");
  }
  if (next.italic != prev.italic) {
    ss << (next.italic ? "\x1B[3m" : "\x1B[23m");
  }
  if (next.strikethrough != prev.strikethrough) {
    ss << (next.strikethrough ? "\x1B[9m" : "\x1B[29m");
  }
  if (next.foreground_color != prev.foreground_color ||
      next.background_color != prev.background_color) {
    ss << "\x1B[" + next.foreground_color.Print(false) + "m";
    ss << "\x1B[" + next.background_color.Print(true) + "m";
  }
}
}  // namespace

std::string Screen::ToString() const {
  std::stringstream ss;
  const Pixel final_pixel;
  const Pixel* prev = &final_pixel;
  for (int y = 0; y < dimy_; ++y) {
    if (y != 0) {
      UpdatePixelStyle(ss, *prev, final_pixel);
      prev = &final_pixel;
      ss << "\r\n";
    }
    bool previous_fullwidth = false;
    for (const auto& pixel : pixels_[y]) {
      if (!previous_fullwidth) {
        UpdatePixelStyle(ss, *prev, pixel);
        prev = &pixel;
        if (pixel.character.empty()) {
          ss << " ";
        } else {
          ss << pixel.character;
        }
      }
      previous_fullwidth = (StringWidth(pixel.character) == 2);
    }
  }
  UpdatePixelStyle(ss, *prev, final_pixel);
  return ss.str();
}

std::string Screen::ResetPosition(bool clear) const {
  std::stringstream ss;
  if (clear) {
    ss << "\r";
    ss << "\x1b[2K";
    for (int y = 1; y < dimy_; ++y) {
      ss << "\x1B[1A";
      ss << "\x1B[2K";
    }
  } else {
    ss << "\r";
    for (int y = 1; y < dimy_; ++y) {
      ss << "\x1B[1A";
    }
  }
  return ss.str();
}

void Screen::Clear() {
  for (auto& line : pixels_) {
    for (auto& cell : line) {
      cell = Pixel();
    }
  }
  cursor_.x = dimx_ - 1;
  cursor_.y = dimy_ - 1;
}

