const std::map<Tile, std::string>& TileInverse() {
  static const std::map<Tile, std::string> inv = [] {
    std::map<Tile, std::string> o;
    for (const auto& it : TileEncoding()) {
      o[it.second] = it.first;
    }
    return o;
  }();
  return inv;
}

void UpgradeLeftRight(std::string& left, std::string& right) {
  const auto& enc = TileEncoding();
  const auto& inv = TileInverse();
  auto il = enc.find(left);
  if (il == enc.end()) return;
  auto ir = enc.find(right);
  if (ir == enc.end()) return;
  const Tile tl = il->second;
  const Tile tr = ir->second;
  if (tl.right == 0 && tr.left != 0) {
    Tile e = tl;
    e.right = tr.left;
    auto u = inv.find(e);
    if (u != inv.end()) left = u->second;
  }
  if (tr.left == 0 && tl.right != 0) {
    Tile e = tr;
    e.left = tl.right;
    auto u = inv.find(e);
    if (u != inv.end()) right = u->second;
  }
}

void UpgradeTopDown(std::string& top, std::string& down) {
  const auto& enc = TileEncoding();
  const auto& inv = TileInverse();
  auto it = enc.find(top);
  if (it == enc.end()) return;
  auto id = enc.find(down);
  if (id == enc.end()) return;
  const Tile tt = it->second;
  const Tile td = id->second;
  if (tt.down == 0 && td.top != 0) {
    Tile e = tt;
    e.down = td.top;
    auto u = inv.find(e);
    if (u != inv.end()) top = u->second;
  }
  if (td.top == 0 && tt.down != 0) {
    Tile e = td;
    e.top = tt.down;
    auto u = inv.find(e);
    if (u != inv.end()) down = u->second;
  }
}

bool ShouldAttemptAutoMerge(const Pixel& p) {
  return p.automerge && p.character.size() == 3;
}
}  // namespace

void Screen::ApplyShader() {
  for (int y = 0; y < dimy_; ++y) {
    for (int x = 0; x < dimx_; ++x) {
      Pixel& cur = pixels_[y][x];
      if (!ShouldAttemptAutoMerge(cur)) continue;
      if (x > 0) {
        Pixel& left = pixels_[y][x - 1];
        if (ShouldAttemptAutoMerge(left)) {
          UpgradeLeftRight(left.character, cur.character);
        }
      }
      if (y > 0) {
        Pixel& top = pixels_[y - 1][x];
        if (ShouldAttemptAutoMerge(top)) {
          UpgradeTopDown(top.character, cur.character);
        }
      }
    }
  }
}

// ---- UTF-8 ----
namespace {
bool EatCodePoint(const std::string& input, size_t start, size_t* end,
                  uint32_t* ucs) {
  if (start >= input.size()) {
    *end = start + 1;
    return false;
  }
  uint8_t C0 = input[start];
  if ((C0 & 0x80) == 0) {
    *end = start + 1;
    *ucs = C0;
    return true;
  }
  if ((C0 & 0xE0) == 0xC0 && start + 1 < input.size()) {
    uint8_t C1 = input[start + 1];
    *end = start + 2;
    *ucs = ((C0 & 0x1F) << 6) | (C1 & 0x3F);
    return true;
  }
  if ((C0 & 0xF0) == 0xE0 && start + 2 < input.size()) {
    uint8_t C1 = input[start + 1];
    uint8_t C2 = input[start + 2];
    *end = start + 3;
    *ucs = ((C0 & 0x0F) << 12) | ((C1 & 0x3F) << 6) | (C2 & 0x3F);
    return true;
  }
  if ((C0 & 0xF8) == 0xF0 && start + 3 < input.size()) {
    uint8_t C1 = input[start + 1];
    uint8_t C2 = input[start + 2];
    uint8_t C3 = input[start + 3];
    *end = start + 4;
    *ucs = ((C0 & 0x07) << 18) | ((C1 & 0x3F) << 12) | ((C2 & 0x3F) << 6) |
           (C3 & 0x3F);
    return true;
  }
  *end = start + 1;
  return false;
}

struct Interval {
  uint32_t first, last;
};

bool InTable(uint32_t c, const Interval* t, size_t n) {
  if (n == 0 || c < t[0].first || c > t[n - 1].last) return false;
  size_t lo = 0, hi = n - 1;
  while (lo <= hi) {
    size_t mid = (lo + hi) / 2;
    if (c > t[mid].last) {
      lo = mid + 1;
    } else if (c < t[mid].first) {
      if (mid == 0) return false;
      hi = mid - 1;
    } else {
      return true;
    }
  }
  return false;
}

