bool IsCombining(uint32_t c) {
  return InTable(c, kCombining, sizeof(kCombining) / sizeof(kCombining[0]));
}
bool IsFullWidth(uint32_t c) {
  if (c < 0x0300) return false;
  return InTable(c, kFullWidth, sizeof(kFullWidth) / sizeof(kFullWidth[0]));
}
bool IsControl(uint32_t c) {
  if (c == 0) return true;
  if (c < 32) return true;
  if (c >= 0x7f && c < 0xa0) return true;
  return false;
}
