#include "dom.hpp"

#include <algorithm>
#include <array>

namespace tui {

// ---------------------------------------------------------------------------
// Node
void Node::ComputeRequirement() {
  for (auto& child : children_) child->ComputeRequirement();
}
void Node::SetBox(Box box) { box_ = box; }
void Node::Render(Screen& screen) {
  for (auto& child : children_) child->Render(screen);
}
void Node::Check(Status* status) {
  for (auto& child : children_) child->Check(status);
  status->need_iteration |= (status->iteration == 0);
}

void Render(Screen& screen, const Element& node) {
  Box box{0, screen.dimx() - 1, 0, screen.dimy() - 1};
  Node::Status status;
  node->Check(&status);
  const int max_iterations = 20;
  while (status.need_iteration && status.iteration < max_iterations) {
    node->ComputeRequirement();
    node->SetBox(box);
    status.need_iteration = false;
    status.iteration++;
    node->Check(&status);
  }
  screen.stencil = box;
  node->Render(screen);
  screen.ApplyShader();
}

Element operator|(Element e, Decorator d) { return d(std::move(e)); }
Element& operator|=(Element& e, Decorator d) {
  e = d(std::move(e));
  return e;
}
Decorator operator|(Decorator a, Decorator b) {
  return [a, b](Element e) { return b(a(std::move(e))); };
}
Elements operator|(Elements es, Decorator d) {
  Elements out;
  for (auto& e : es) out.push_back(d(e));
  return out;
}

namespace {
Elements Unpack(Element e) {
  Elements v;
  v.push_back(std::move(e));
  return v;
}

class NodeDecorator : public Node {
 public:
  explicit NodeDecorator(Element child) : Node(Unpack(std::move(child))) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    children_[0]->SetBox(box);
  }
};

// ---------------------------------------------------------------------------
class Text : public Node {
 public:
  explicit Text(std::string t) : text_(std::move(t)) {}
  void ComputeRequirement() override {
    requirement_.min_x = StringWidth(text_);
    requirement_.min_y = 1;
  }
  void Render(Screen& screen) override {
    int x = box_.x_min;
    const int y = box_.y_min;
    if (y > box_.y_max) return;
    for (const auto& cell : Utf8ToGlyphs(text_)) {
      if (x > box_.x_max) return;
      screen.PixelAt(x, y).character = cell;
      ++x;
    }
  }

 private:
  std::string text_;
};

class Empty : public Node {
 public:
  void ComputeRequirement() override {
    requirement_.min_x = 0;
    requirement_.min_y = 0;
  }
};

