    {"│", "─"},
    {"╏", "╍"},
    {"┃", "━"},
    {"║", "═"},
    {"│", "─"},
    {" ", " "},
}};

class SeparatorAuto : public Node {
 public:
  explicit SeparatorAuto(BorderStyle style) : style_(style) {}
  void ComputeRequirement() override {
    requirement_.min_x = 1;
    requirement_.min_y = 1;
