}};

class Border : public Node {
 public:
  Border(Elements children, BorderStyle style)
      : Node(std::move(children)), style_(style) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
    requirement_.min_x += 2;
    requirement_.min_y += 2;
    if (children_.size() == 2) {
      requirement_.min_x =
          std::max(requirement_.min_x, children_[1]->requirement().min_x + 2);
    }
    requirement_.selected_box.x_min++;
    requirement_.selected_box.x_max++;
    requirement_.selected_box.y_min++;
    requirement_.selected_box.y_max++;
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    if (children_.size() == 2) {
      Box title_box;
      title_box.x_min = box.x_min + 1;
      title_box.x_max = std::min(box.x_max - 1,
                                 box.x_min + children_[1]->requirement().min_x);
      title_box.y_min = box.y_min;
      title_box.y_max = box.y_min;
      children_[1]->SetBox(title_box);
    }
    box.x_min++;
    box.x_max--;
    box.y_min++;
    box.y_max--;
    children_[0]->SetBox(box);
  }
  void Render(Screen& screen) override {
    children_[0]->Render(screen);
    if (box_.x_min >= box_.x_max || box_.y_min >= box_.y_max) return;
    const auto& cs = kBorderCharset[style_];
    screen.at(box_.x_min, box_.y_min) = cs[0];
    screen.at(box_.x_max, box_.y_min) = cs[1];
    screen.at(box_.x_min, box_.y_max) = cs[2];
    screen.at(box_.x_max, box_.y_max) = cs[3];
    for (int x = box_.x_min + 1; x < box_.x_max; ++x) {
      Pixel& p1 = screen.PixelAt(x, box_.y_min);
      p1.character = cs[4];
      p1.automerge = true;
      Pixel& p2 = screen.PixelAt(x, box_.y_max);
      p2.character = cs[4];
      p2.automerge = true;
    }
    for (int y = box_.y_min + 1; y < box_.y_max; ++y) {
      Pixel& p3 = screen.PixelAt(box_.x_min, y);
      p3.character = cs[5];
      p3.automerge = true;
      Pixel& p4 = screen.PixelAt(box_.x_max, y);
      p4.character = cs[5];
      p4.automerge = true;
    }
    if (children_.size() == 2) children_[1]->Render(screen);
  }

 private:
  BorderStyle style_;
};

// ---------------------------------------------------------------------------
// Box helper
struct BoxElement {
  int min_size = 0;
  int flex_grow = 0;
  int flex_shrink = 0;
  int size = 0;
};

void ComputeGrow(std::vector<BoxElement>* elements, int extra_space,
                 int flex_grow_sum) {
  for (BoxElement& e : *elements) {
    const int added = extra_space * e.flex_grow / std::max(flex_grow_sum, 1);
    extra_space -= added;
    flex_grow_sum -= e.flex_grow;
    e.size = e.min_size + added;
  }
}

void ComputeShrinkEasy(std::vector<BoxElement>* elements, int extra_space,
                       int flex_shrink_sum) {
  for (BoxElement& e : *elements) {
    const int added = extra_space * e.min_size * e.flex_shrink /
                      std::max(flex_shrink_sum, 1);
    extra_space -= added;
    flex_shrink_sum -= e.flex_shrink * e.min_size;
    e.size = e.min_size + added;
  }
}

void ComputeShrinkHard(std::vector<BoxElement>* elements, int extra_space,
                       int size) {
  for (BoxElement& e : *elements) {
    if (e.flex_shrink != 0) {
      e.size = 0;
      continue;
    }
    const int added = extra_space * e.min_size / std::max(1, size);
    extra_space -= added;
    size -= e.min_size;
    e.size = e.min_size + added;
  }
}

void BoxCompute(std::vector<BoxElement>* elements, int target_size) {
  int size = 0;
  int flex_grow_sum = 0;
  int flex_shrink_sum = 0;
  int flex_shrink_size = 0;
  for (auto& e : *elements) {
    flex_grow_sum += e.flex_grow;
    flex_shrink_sum += e.min_size * e.flex_shrink;
    if (e.flex_shrink != 0) flex_shrink_size += e.min_size;
    size += e.min_size;
  }
  const int extra_space = target_size - size;
  if (extra_space >= 0) {
    ComputeGrow(elements, extra_space, flex_grow_sum);
  } else if (flex_shrink_size + extra_space >= 0) {
    ComputeShrinkEasy(elements, extra_space, flex_shrink_sum);
  } else {
    ComputeShrinkHard(elements, extra_space + flex_shrink_size,
                      size - flex_shrink_size);
  }
}

class HBox : public Node {
 public:
  explicit HBox(Elements children) : Node(std::move(children)) {}
  void ComputeRequirement() override {
    requirement_ = Requirement();
    for (auto& child : children_) {
      child->ComputeRequirement();
      const auto& r = child->requirement();
      if (requirement_.selection < r.selection) {
        requirement_.selection = r.selection;
        requirement_.selected_box = r.selected_box;
        requirement_.selected_box.x_min += requirement_.min_x;
        requirement_.selected_box.x_max += requirement_.min_x;
      }
      requirement_.min_x += r.min_x;
      requirement_.min_y = std::max(requirement_.min_y, r.min_y);
    }
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    std::vector<BoxElement> elements(children_.size());
    for (size_t i = 0; i < children_.size(); ++i) {
      const auto& r = children_[i]->requirement();
      elements[i].min_size = r.min_x;
      elements[i].flex_grow = r.flex_grow_x;
      elements[i].flex_shrink = r.flex_shrink_x;
    }
    BoxCompute(&elements, box.x_max - box.x_min + 1);
    int x = box.x_min;
    for (size_t i = 0; i < children_.size(); ++i) {
      box.x_min = x;
      box.x_max = x + elements[i].size - 1;
      children_[i]->SetBox(box);
      x = box.x_max + 1;
    }
  }
};

class VBox : public Node {
 public:
  explicit VBox(Elements children) : Node(std::move(children)) {}
  void ComputeRequirement() override {
    requirement_ = Requirement();
    for (auto& child : children_) {
      child->ComputeRequirement();
      const auto& r = child->requirement();
      if (requirement_.selection < r.selection) {
        requirement_.selection = r.selection;
        requirement_.selected_box = r.selected_box;
        requirement_.selected_box.y_min += requirement_.min_y;
        requirement_.selected_box.y_max += requirement_.min_y;
      }
      requirement_.min_y += r.min_y;
      requirement_.min_x = std::max(requirement_.min_x, r.min_x);
    }
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    std::vector<BoxElement> elements(children_.size());
    for (size_t i = 0; i < children_.size(); ++i) {
      const auto& r = children_[i]->requirement();
      elements[i].min_size = r.min_y;
      elements[i].flex_grow = r.flex_grow_y;
      elements[i].flex_shrink = r.flex_shrink_y;
    }
    BoxCompute(&elements, box.y_max - box.y_min + 1);
    int y = box.y_min;
    for (size_t i = 0; i < children_.size(); ++i) {
      box.y_min = y;
      box.y_max = y + elements[i].size - 1;
      children_[i]->SetBox(box);
      y = box.y_max + 1;
    }
  }
};

class DBox : public Node {
 public:
  explicit DBox(Elements children) : Node(std::move(children)) {}
  void ComputeRequirement() override {
    requirement_ = Requirement();
    for (auto& child : children_) {
      child->ComputeRequirement();
      const auto& r = child->requirement();
      requirement_.min_x = std::max(requirement_.min_x, r.min_x);
      requirement_.min_y = std::max(requirement_.min_y, r.min_y);
      if (requirement_.selection < r.selection) {
        requirement_.selection = r.selection;
        requirement_.selected_box = r.selected_box;
      }
    }
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    for (auto& child : children_) child->SetBox(box);
  }
};

