class SelectNode : public Node {
 public:
  explicit SelectNode(Element child) : Node(Unpack(std::move(child))) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
    auto& sb = requirement_.selected_box;
    sb.x_min = 0;
    sb.y_min = 0;
    sb.x_max = requirement_.min_x - 1;
    sb.y_max = requirement_.min_y - 1;
    requirement_.selection = Requirement::SELECTED;
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    children_[0]->SetBox(box);
  }
};

class FocusNode : public SelectNode {
 public:
  using SelectNode::SelectNode;
  void ComputeRequirement() override {
    SelectNode::ComputeRequirement();
    requirement_.selection = Requirement::FOCUSED;
  }
  void Render(Screen& screen) override {
    SelectNode::Render(screen);
    screen.SetCursor(Screen::Cursor{box_.x_max, box_.y_max});
  }
};

class Frame : public Node {
 public:
  Frame(Element child, bool x_frame, bool y_frame)
      : Node(Unpack(std::move(child))), x_frame_(x_frame), y_frame_(y_frame) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    auto& selected_box = requirement_.selected_box;
    Box children_box = box;
    if (x_frame_) {
      const int external_dimx = box.x_max - box.x_min;
      const int internal_dimx = std::max(requirement_.min_x, external_dimx);
      const int focused_dimx = selected_box.x_max - selected_box.x_min;
      int dx = selected_box.x_min - external_dimx / 2 + focused_dimx / 2;
      dx = std::max(0, std::min(internal_dimx - external_dimx - 1, dx));
      children_box.x_min = box.x_min - dx;
      children_box.x_max = box.x_min + internal_dimx - dx;
    }
    if (y_frame_) {
      const int external_dimy = box.y_max - box.y_min;
      const int internal_dimy = std::max(requirement_.min_y, external_dimy);
      const int focused_dimy = selected_box.y_max - selected_box.y_min;
      int dy = selected_box.y_min - external_dimy / 2 + focused_dimy / 2;
      dy = std::max(0, std::min(internal_dimy - external_dimy - 1, dy));
      children_box.y_min = box.y_min - dy;
      children_box.y_max = box.y_min + internal_dimy - dy;
    }
    children_[0]->SetBox(children_box);
  }
  void Render(Screen& screen) override {
    Box saved = screen.stencil;
    screen.stencil = Box::Intersection(box_, screen.stencil);
    children_[0]->Render(screen);
    screen.stencil = saved;
  }

 private:
  bool x_frame_;
  bool y_frame_;
};

class VScrollIndicator : public NodeDecorator {
 public:
  using NodeDecorator::NodeDecorator;
  void ComputeRequirement() override {
    NodeDecorator::ComputeRequirement();
    requirement_ = children_[0]->requirement();
    requirement_.min_x++;
  }
  void SetBox(Box box) override {
    box_ = box;
    box.x_max--;
    children_[0]->SetBox(box);
  }
  void Render(Screen& screen) override {
    NodeDecorator::Render(screen);
    const Box& stencil = screen.stencil;
    const int size_inner = box_.y_max - box_.y_min;
    if (size_inner <= 0) return;
    const int size_outter = stencil.y_max - stencil.y_min + 1;
    if (size_outter >= size_inner) return;
    int sz = 2 * size_outter * size_outter / size_inner;
    sz = std::max(sz, 1);
    const int start_y =
        2 * stencil.y_min +
        static_cast<int>(2 * float(stencil.y_min - box_.y_min) *
                         float(size_outter) / float(size_inner));
    const int x = stencil.x_max;
    for (int y = stencil.y_min; y <= stencil.y_max; ++y) {
      const int y_up = 2 * y + 0;
      const int y_down = 2 * y + 1;
      const bool up = (start_y <= y_up) && (y_up <= start_y + sz);
      const bool down = (start_y <= y_down) && (y_down <= start_y + sz);
      const char* c = up ? (down ? "┃" : "╹") : (down ? "╻" : " ");
      screen.PixelAt(x, y) = Pixel();
      screen.PixelAt(x, y).character = c;
    }
  }
};

class Reflect : public Node {
 public:
  Reflect(Element child, Box& box)
      : Node(Unpack(std::move(child))), reflected_box_(box) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
  }
  void SetBox(Box box) override {
    reflected_box_ = box;
    Node::SetBox(box);
    children_[0]->SetBox(box);
  }
  void Render(Screen& screen) override {
    reflected_box_ = Box::Intersection(screen.stencil, reflected_box_);
    Node::Render(screen);
  }

 private:
  Box& reflected_box_;
};

class PixelStyle : public NodeDecorator {
 public:
  PixelStyle(Element child, std::function<void(Pixel&)> f)
      : NodeDecorator(std::move(child)), f_(std::move(f)) {}
  void Render(Screen& screen) override {
    for (int y = box_.y_min; y <= box_.y_max; ++y) {
      for (int x = box_.x_min; x <= box_.x_max; ++x) {
        f_(screen.PixelAt(x, y));
      }
    }
    Node::Render(screen);
  }

 private:
  std::function<void(Pixel&)> f_;
};

class ClearUnder : public NodeDecorator {
 public:
  using NodeDecorator::NodeDecorator;
  void Render(Screen& screen) override {
    for (int y = box_.y_min; y <= box_.y_max; ++y) {
      for (int x = box_.x_min; x <= box_.x_max; ++x) {
        screen.PixelAt(x, y) = Pixel();
        screen.PixelAt(x, y).character = " ";
      }
    }
    Node::Render(screen);
  }
};

