#include "component.hpp"

#include <algorithm>

namespace tui {

ComponentBase::ComponentBase(Components children) {
  for (auto& c : children) Add(c);
}

ComponentBase::~ComponentBase() { DetachAllChildren(); }

void ComponentBase::Add(Component child) {
  child->Detach();
  child->parent_ = this;
  children_.push_back(std::move(child));
}

void ComponentBase::Detach() {
  if (parent_ == nullptr) return;
  auto& siblings = parent_->children_;
  auto it = std::find_if(siblings.begin(), siblings.end(),
                         [this](const Component& c) { return c.get() == this; });
  ComponentBase* p = parent_;
  parent_ = nullptr;
  if (it != siblings.end()) siblings.erase(it);
  (void)p;
}

void ComponentBase::DetachAllChildren() {
  while (!children_.empty()) children_[0]->Detach();
}

Element ComponentBase::Render() { return OnRender(); }

Element ComponentBase::OnRender() {
  if (children_.size() == 1) return children_.front()->Render();
  return text("Not implemented component");
}

bool ComponentBase::OnEvent(Event event) {
  for (auto& child : children_) {
    if (child->OnEvent(event)) return true;
  }
  return false;
}

Component ComponentBase::ActiveChild() {
  for (auto& child : children_) {
    if (child->Focusable()) return child;
  }
  return nullptr;
}

bool ComponentBase::Focusable() const {
  for (const auto& child : children_) {
    if (child->Focusable()) return true;
  }
  return false;
}

bool ComponentBase::Active() const {
  return parent_ == nullptr || parent_->ActiveChild().get() == this;
}

bool ComponentBase::Focused() const {
  const ComponentBase* current = this;
  while (current && current->Active()) current = current->parent_;
  return !current && Focusable();
}

void ComponentBase::SetActiveChild(ComponentBase*) {}

void ComponentBase::TakeFocus() {
  ComponentBase* child = this;
  while (ComponentBase* parent = child->parent_) {
    parent->SetActiveChild(child);
    child = parent;
  }
}

// ---------------------------------------------------------------------------
namespace {

class ContainerBase : public ComponentBase {
 public:
  ContainerBase(Components children, int* selector)
      : selector_(selector ? selector : &selected_) {
    for (auto& c : children) Add(c);
  }

  bool OnEvent(Event event) override {
    if (event.is_mouse()) return false;
    if (!Focused()) return false;
    if (ActiveChild() && ActiveChild()->OnEvent(event)) return true;
    return EventHandler(event);
  }

  Component ActiveChild() override {
    if (children_.empty()) return nullptr;
    return children_[static_cast<size_t>(*selector_) % children_.size()];
  }

  void SetActiveChild(ComponentBase* child) override {
    for (size_t i = 0; i < children_.size(); ++i) {
      if (children_[i].get() == child) {
        *selector_ = static_cast<int>(i);
        return;
      }
    }
  }

 protected:
  virtual bool EventHandler(Event) { return false; }

  void MoveSelector(int dir) {
    for (int i = *selector_ + dir; i >= 0 && i < int(children_.size());
         i += dir) {
      if (children_[i]->Focusable()) {
        *selector_ = i;
        return;
      }
    }
  }

  void MoveSelectorWrap(int dir) {
    if (children_.empty()) return;
    for (size_t offset = 1; offset < children_.size(); ++offset) {
      const size_t i =
          (size_t(*selector_ + int(offset) * dir + int(children_.size()))) %
          children_.size();
      if (children_[i]->Focusable()) {
        *selector_ = static_cast<int>(i);
        return;
      }
    }
  }

  int selected_ = 0;
  int* selector_ = nullptr;
};

class VerticalContainer : public ContainerBase {
 public:
  using ContainerBase::ContainerBase;
  Element OnRender() override {
    Elements elements;
    for (auto& it : children_) elements.push_back(it->Render());
    if (elements.empty()) return text("Empty container");
    return vbox(std::move(elements));
  }
  bool EventHandler(Event event) override {
    const int old_selected = *selector_;
    if (event == Event::ArrowUp || event == Event::Character('k')) MoveSelector(-1);
    if (event == Event::ArrowDown || event == Event::Character('j')) MoveSelector(+1);
    if (event == Event::Home) {
      for (size_t i = 0; i < children_.size(); ++i) MoveSelector(-1);
    }
    if (event == Event::End) {
      for (size_t i = 0; i < children_.size(); ++i) MoveSelector(1);
    }
    if (event == Event::Tab) MoveSelectorWrap(+1);
    if (event == Event::TabReverse) MoveSelectorWrap(-1);
    *selector_ = std::max(0, std::min(int(children_.size()) - 1, *selector_));
    return old_selected != *selector_;
  }
};

class HorizontalContainer : public ContainerBase {
 public:
  using ContainerBase::ContainerBase;
  Element OnRender() override {
    Elements elements;
    for (auto& it : children_) elements.push_back(it->Render());
    if (elements.empty()) return text("Empty container");
    return hbox(std::move(elements));
  }
  bool EventHandler(Event event) override {
    const int old_selected = *selector_;
    if (event == Event::ArrowLeft || event == Event::Character('h')) MoveSelector(-1);
    if (event == Event::ArrowRight || event == Event::Character('l')) MoveSelector(+1);
    if (event == Event::Tab) MoveSelectorWrap(+1);
    if (event == Event::TabReverse) MoveSelectorWrap(-1);
    *selector_ = std::max(0, std::min(int(children_.size()) - 1, *selector_));
    return old_selected != *selector_;
  }
};

class TabContainer : public ContainerBase {
 public:
  using ContainerBase::ContainerBase;
  Element OnRender() override {
    Component active_child = ActiveChild();
