class MenuBase : public ComponentBase {
 public:
  MenuBase(const std::vector<std::string>* entries, int* selected,
           MenuOption option)
      : entries_(entries), selected_(selected), option_(std::move(option)) {
    if (option_.focused_entry) focused_entry_ = option_.focused_entry;
  }

  int size() const { return static_cast<int>(entries_->size()); }

  void Clamp() {
    *selected_ = std::max(0, std::min(size() - 1, *selected_));
    *focused_entry_ = std::max(0, std::min(size() - 1, *focused_entry_));
  }

  Element OnRender() override {
    Clamp();
    Elements elements;
    const bool is_menu_focused = Focused();
    for (int i = 0; i < size(); ++i) {
      const bool is_focused = (*focused_entry_ == i) && is_menu_focused;
      const bool is_selected = (*selected_ == i);
      EntryState state{(*entries_)[i], false, is_selected, is_focused, i};
      Element element;
      if (option_.transform) {
        element = option_.transform(state);
      } else {
        std::string label = (state.active ? "> " : "  ") + state.label;
        element = text(label);
        if (state.focused) element = element | inverted;
        if (state.active) element = element | bold;
      }
      if (*focused_entry_ == i) {
        element = is_menu_focused ? focus(element) : select(element);
      }
      elements.push_back(element);
    }
    return vbox(std::move(elements));
  }

  bool OnEvent(Event event) override {
    Clamp();
    if (event.is_mouse()) return false;
    if (Focused()) {
      const int old_selected = *selected_;
      if (event == Event::ArrowUp || event == Event::Character('k')) {
        (*selected_)--;
      }
      if (event == Event::ArrowDown || event == Event::Character('j')) {
        (*selected_)++;
      }
      if (event == Event::Home) *selected_ = 0;
      if (event == Event::End) *selected_ = size() - 1;
      if (event == Event::Tab && size()) {
        *selected_ = (*selected_ + 1) % size();
      }
      if (event == Event::TabReverse && size()) {
        *selected_ = (*selected_ + size() - 1) % size();
      }
      *selected_ = std::max(0, std::min(size() - 1, *selected_));
      if (*selected_ != old_selected) {
        *focused_entry_ = *selected_;
        if (option_.on_change) option_.on_change();
        return true;
      }
    }
    if (event == Event::Return) {
      if (option_.on_enter) option_.on_enter();
      return true;
    }
    return false;
  }

  bool Focusable() const override { return !entries_->empty(); }

 private:
  const std::vector<std::string>* entries_;
  int* selected_;
  MenuOption option_;
  int focused_entry_storage_ = 0;
  int* focused_entry_ = &focused_entry_storage_;
};

