class InputBase : public ComponentBase {
 public:
  InputBase(std::string* content, InputOption option)
      : content_(content), option_(std::move(option)) {
    cursor_position_ = static_cast<int>(content_->size());
  }

  std::string Shown(const std::string& s) const {
    if (!option_.password) return s;
    std::string out;
    for (size_t i = 0; i < s.size(); ++i) {
      unsigned char c = s[i];
      if ((c & 0xC0) == 0x80) continue;
      out += "•";
    }
    return out;
  }

  Element OnRender() override {
    const bool is_focused = Focused();
    auto transform = option_.transform;
    auto apply = [&](Element e, bool placeholder) {
      if (transform) return transform(std::move(e), is_focused, false, placeholder);
      e = e | color(Color::White);
      if (placeholder) e = e | dim;
      if (is_focused) e = e | inverted;
      return e;
    };
    if (content_->empty()) {
      auto element = frame(xflex(text(option_.placeholder)));
      element = apply(std::move(element), true);
      return element | focus;
    }
    cursor_position_ =
        std::max(0, std::min(cursor_position_, int(content_->size())));
    const std::string& line = *content_;
    Element element;
    if (cursor_position_ >= int(line.size())) {
      Element cur = text(" ");
      cur = is_focused ? focus(cur) : select(cur);
      element = xflex(hbox({text(Shown(line)), cur}));
    } else {
      size_t end = cursor_position_ + 1;
      while (end < line.size() && ((unsigned char)line[end] & 0xC0) == 0x80) end++;
      Element cur = text(Shown(line.substr(cursor_position_, end - cursor_position_)));
      cur = is_focused ? focus(cur) : select(cur);
      element = xflex(hbox({text(Shown(line.substr(0, cursor_position_))), cur,
                            text(Shown(line.substr(end)))}));
    }
    element = frame(vbox({element}));
    return xflex(apply(std::move(element), false));
  }

  bool OnEvent(Event event) override {
    cursor_position_ =
        std::max(0, std::min(cursor_position_, int(content_->size())));
    if (event.is_mouse()) return false;
    if (event == Event::Return) {
      if (option_.on_enter) option_.on_enter();
      return true;
    }
    if (event == Event::Backspace) {
      if (cursor_position_ == 0) return false;
      size_t start = cursor_position_ - 1;
      while (start > 0 && ((unsigned char)(*content_)[start] & 0xC0) == 0x80) start--;
      content_->erase(start, cursor_position_ - start);
      cursor_position_ = static_cast<int>(start);
      if (option_.on_change) option_.on_change();
      return true;
    }
    if (event == Event::Delete) {
      if (cursor_position_ == int(content_->size())) return false;
      size_t end = cursor_position_ + 1;
      while (end < content_->size() && ((unsigned char)(*content_)[end] & 0xC0) == 0x80) end++;
      content_->erase(cursor_position_, end - cursor_position_);
      if (option_.on_change) option_.on_change();
      return true;
    }
    if (event == Event::ArrowLeft) {
      if (cursor_position_ == 0) return false;
      cursor_position_--;
      while (cursor_position_ > 0 &&
             ((unsigned char)(*content_)[cursor_position_] & 0xC0) == 0x80)
        cursor_position_--;
      return true;
    }
    if (event == Event::ArrowRight) {
      if (cursor_position_ == int(content_->size())) return false;
      cursor_position_++;
      while (cursor_position_ < int(content_->size()) &&
             ((unsigned char)(*content_)[cursor_position_] & 0xC0) == 0x80)
        cursor_position_++;
      return true;
    }
    if (event == Event::Home) {
      cursor_position_ = 0;
      return true;
    }
    if (event == Event::End) {
      cursor_position_ = static_cast<int>(content_->size());
      return true;
    }
    if (event.is_character()) {
      content_->insert(cursor_position_, event.character());
      cursor_position_ += static_cast<int>(event.character().size());
      if (option_.on_change) option_.on_change();
      return true;
    }
    return false;
  }

  bool Focusable() const override { return true; }

 private:
  std::string* content_;
  InputOption option_;
  int cursor_position_ = 0;
};

