void ComponentBase::Detach() {
  if (parent_ == nullptr) return;
  auto& siblings = parent_->children_;
  auto it = std::find_if(siblings.begin(), siblings.end(),
                         [this](const Component& c) { return c.get() == this; });
  ComponentBase* p = parent_;
  parent_ = nullptr;
  if (it != siblings.end()) siblings.erase(it);
  (void)p;
}

void ComponentBase::DetachAllChildren() {
  while (!children_.empty()) children_[0]->Detach();
}

Element ComponentBase::Render() { return OnRender(); }

Element ComponentBase::OnRender() {
  if (children_.size() == 1) return children_.front()->Render();
  return text("Not implemented component");
