// Parse one event from `in` starting at pos. Returns number of bytes consumed,
// 0 if incomplete. Sets *ev and *drop.
size_t ParseOne(const std::string& in, size_t pos, Event* ev, bool* drop) {
  *drop = false;
  unsigned char c = in[pos];
  auto special = [&](size_t len) {
    std::string s = in.substr(pos, len);
    auto it = Uniformize().find(s);
    if (it != Uniformize().end()) s = it->second;
    *ev = Event::Special(s);
    return len;
  };
  if (c == 24 || c == 26) {
    *drop = true;
    return 1;
  }
  if (c == 0x1B) {
    if (pos + 1 >= in.size()) return 0;
    unsigned char c1 = in[pos + 1];
    if (c1 == '[') {
      // CSI
      size_t i = pos + 2;
      if (i < in.size() && in[i] == '[') {
        // linux console F-keys: ESC [ [ X
        if (i + 1 >= in.size()) return 0;
        return special(4);
      }
      bool mouse_sgr = (i < in.size() && in[i] == '<');
      while (i < in.size()) {
        unsigned char d = in[i];
        if (d >= 0x40 && d <= 0x7E && !(i == pos + 2 && d == '<')) break;
        ++i;
      }
      if (i >= in.size()) return 0;
      size_t len = i - pos + 1;
      unsigned char fin = in[i];
      if (mouse_sgr && (fin == 'M' || fin == 'm')) {
        Mouse m;
        int b = 0, x = 0, y = 0;
        std::sscanf(in.substr(pos + 3, len - 4).c_str(), "%d;%d;%d", &b, &x, &y);
        m.x = x - 1;
        m.y = y - 1;
        m.button = static_cast<Mouse::Button>((b & 3) + ((b & 64) >> 4));
        m.motion = fin == 'M' ? Mouse::Pressed : Mouse::Released;
        if (b & 32) m.motion = Mouse::Moved;
        *ev = Event::MouseEvent(in.substr(pos, len), m);
        return len;
      }
      if (fin == 'R') {
        *ev = Event::CursorReport(in.substr(pos, len), 0, 0);
        return len;
      }
      if (fin == 'M' && len == 3) {
        // X10 mouse: ESC [ M b x y
        if (pos + 5 >= in.size() + 0 && pos + 6 > in.size()) return 0;
        Mouse m;
        *ev = Event::MouseEvent(in.substr(pos, 6), m);
        return 6;
      }
      return special(len);
    }
    if (c1 == 'O') {
      if (pos + 2 >= in.size()) return 0;
      return special(3);
    }
    if (c1 == 'P' || c1 == ']' || c1 == '_' || c1 == '^' || c1 == 'X') {
      // DCS / OSC: until ST (ESC \) or BEL
      size_t i = pos + 2;
      while (i < in.size()) {
        if (in[i] == '\x07') {
          *drop = true;
          return i - pos + 1;
        }
        if (in[i] == '\x1B' && i + 1 < in.size() && in[i + 1] == '\\') {
          *drop = true;
          return i - pos + 2;
        }
        if (in[i] == '\x1B' && i + 1 >= in.size()) return 0;
        ++i;
      }
      return 0;
    }
    if (c1 == 0x1B) {
      // ESC ESC: treat first as escape
      *ev = Event::Special("\x1B");
      return 1;
    }
    // Alt + key
    size_t len = 2;
    unsigned char k = c1;
    if (k >= 0xC0) {
      size_t need = k >= 0xF0 ? 4 : k >= 0xE0 ? 3 : 2;
      if (pos + 1 + need > in.size()) return 0;
      len = 1 + need;
    }
    *ev = Event::Special(in.substr(pos, len));
    return len;
  }
  if (c < 32 || c == 127) {
    return special(1);
  }
