      if (fin == 'R') {
        *ev = Event::CursorReport(in.substr(pos, len), 0, 0);
        return len;
      }
      if (fin == 'M' && len == 3) {
        // X10 mouse: ESC [ M b x y
        if (pos + 5 >= in.size() + 0 && pos + 6 > in.size()) return 0;
        Mouse m;
        *ev = Event::MouseEvent(in.substr(pos, 6), m);
        return 6;
      }
      return special(len);
    }
    if (c1 == 'O') {
      if (pos + 2 >= in.size()) return 0;
      return special(3);
    }
    if (c1 == 'P' || c1 == ']' || c1 == '_' || c1 == '^' || c1 == 'X') {
      // DCS / OSC: until ST (ESC \) or BEL
      size_t i = pos + 2;
      while (i < in.size()) {
        if (in[i] == '\x07') {
          *drop = true;
          return i - pos + 1;
        }
        if (in[i] == '\x1B' && i + 1 < in.size() && in[i + 1] == '\\') {
          *drop = true;
          return i - pos + 2;
        }
        if (in[i] == '\x1B' && i + 1 >= in.size()) return 0;
        ++i;
      }
      return 0;
    }
    if (c1 == 0x1B) {
      // ESC ESC: treat first as escape
      *ev = Event::Special("\x1B");
      return 1;
    }
    // Alt + key
    size_t len = 2;
    unsigned char k = c1;
    if (k >= 0xC0) {
      size_t need = k >= 0xF0 ? 4 : k >= 0xE0 ? 3 : 2;
      if (pos + 1 + need > in.size()) return 0;
      len = 1 + need;
    }
    *ev = Event::Special(in.substr(pos, len));
    return len;
  }
  if (c < 32 || c == 127) {
    return special(1);
  }
  // UTF-8
  size_t need = 1;
  if (c >= 0xF0) need = 4;
  else if (c >= 0xE0) need = 3;
  else if (c >= 0xC0) need = 2;
  if (pos + need > in.size()) return 0;
  *ev = Event::Character(in.substr(pos, need));
  return need;
}

}  // namespace

ScreenInteractive::ScreenInteractive() : Screen(0, 0) {}

ScreenInteractive& ScreenInteractive::Fullscreen() {
  static ScreenInteractive s;
  return s;
}

ScreenInteractive* ScreenInteractive::Active() { return g_active; }

void ScreenInteractive::Flush() { WriteOut(std::string(1, '\0')); }

void ScreenInteractive::Install() {
  if (installed_) return;
  installed_ = true;
  WriteOut("\x1BP$q q\x1B\\");
  if (tcgetattr(STDIN_FILENO, &g_saved_termios) == 0) {
    g_have_termios = true;
    struct termios t = g_saved_termios;
    t.c_lflag &= ~(ICANON | ECHO | ISIG | IEXTEN);
    t.c_iflag &= ~(IXON | ICRNL | BRKINT | INPCK | ISTRIP);
    t.c_cc[VMIN] = 0;
    t.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &t);
  }
  WriteOut("\x1B[?1049h");
  WriteOut("\x1B[?7l");
  WriteOut("\x1B[?1000h");
  WriteOut("\x1B[?1003h");
  WriteOut("\x1B[?1015h");
  WriteOut("\x1B[?1006h");
  Flush();
  // Force a full redraw after (re)install.
  dimx_ = 0;
  dimy_ = 0;
  pixels_.clear();
  reset_cursor_position_.clear();
}

void ScreenInteractive::Uninstall() {
  if (!installed_) return;
  installed_ = false;
  WriteOut(reset_cursor_position_);
  reset_cursor_position_.clear();
  WriteOut("\x1B[?1006l\x1B[?1015l\x1B[?1003l\x1B[?1000l");
  WriteOut("\x1B[?7h");
  WriteOut("\x1B[?1049l");
  WriteOut("\x1B[?25h\x1B[1 q");
  Flush();
  if (g_have_termios) tcsetattr(STDIN_FILENO, TCSANOW, &g_saved_termios);
}

void ScreenInteractive::WithRestoredIO(const std::function<void()>& fn) {
  Uninstall();
  fn();
  Install();
}

void ScreenInteractive::Exit() { quit_ = true; }

void ScreenInteractive::PostEvent(Event e) { posted_.push_back(e); }

void ScreenInteractive::Draw(Component component) {
  auto document = component->Render();
  int w = 80, h = 24;
  TerminalSize(&w, &h);
  const bool resized = (w != dimx_) || (h != dimy_);
  std::string out;
  out += reset_cursor_position_;
  reset_cursor_position_.clear();
  out += ResetPosition(resized);
  if (resized) {
    dimx_ = w;
    dimy_ = h;
    pixels_ = std::vector<std::vector<Pixel>>(h, std::vector<Pixel>(w));
    cursor_.x = dimx_ - 1;
    cursor_.y = dimy_ - 1;
  }
  stencil = Box{0, dimx_ - 1, 0, dimy_ - 1};
  tui::Render(*this, document);
  const int dx = dimx_ - 1 - cursor_.x;
  const int dy = dimy_ - 1 - cursor_.y;
  set_cursor_position_.clear();
  if (dy != 0) {
    set_cursor_position_ += "\x1B[" + std::to_string(dy) + "A";
    reset_cursor_position_ += "\x1B[" + std::to_string(dy) + "B";
  }
  if (dx != 0) {
    set_cursor_position_ += "\x1B[" + std::to_string(dx) + "D";
    reset_cursor_position_ += "\x1B[" + std::to_string(dx) + "C";
  }
  set_cursor_position_ += "\x1B[?25l";
  out += ToString();
  out += set_cursor_position_;
  WriteOut(out);
  Flush();
  Clear();
}

void ScreenInteractive::Dispatch(Component component, Event e) {
  if (e == Event::CtrlC) {
    quit_ = true;
    return;
  }
  component->OnEvent(e);
}

void ScreenInteractive::Loop(Component component) {
  ScreenInteractive* previous = g_active;
  g_active = this;
  struct sigaction sa {};
  sa.sa_handler = OnResize;
  sigemptyset(&sa.sa_mask);
  sigaction(SIGWINCH, &sa, nullptr);
  signal(SIGPIPE, SIG_IGN);

  Install();
  Draw(component);
  auto last_input = std::chrono::steady_clock::now();
  while (!quit_) {
    struct pollfd pfd {};
    pfd.fd = STDIN_FILENO;
    pfd.events = POLLIN;
    int timeout = pending_.empty() ? 500 : 20;
    int r = poll(&pfd, 1, timeout);
    bool changed = false;
    if (r > 0 && (pfd.revents & POLLIN)) {
      char buf[4096];
      ssize_t n = ::read(STDIN_FILENO, buf, sizeof(buf));
      if (n > 0) {
        pending_.append(buf, static_cast<size_t>(n));
        last_input = std::chrono::steady_clock::now();
      } else if (n == 0) {
        // stdin closed
        quit_ = true;
        break;
      }
    } else if (r > 0 && (pfd.revents & (POLLHUP | POLLERR))) {
      quit_ = true;
      break;
    }
    // Parse pending.
    size_t pos = 0;
    while (pos < pending_.size() && !quit_) {
      Event ev;
      bool drop = false;
      size_t used = ParseOne(pending_, pos, &ev, &drop);
      if (used == 0) {
        auto now = std::chrono::steady_clock::now();
        auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(now - last_input).count();
        if (ms >= 50) {
          // Timeout: flush the incomplete sequence as-is.
          std::string rest = pending_.substr(pos);
          if (rest == "\x1B") {
            Dispatch(component, Event::Escape);
          } else {
            Dispatch(component, Event::Special(rest));
          }
          pos = pending_.size();
          changed = true;
        }
        break;
      }
      pos += used;
      if (drop) continue;
      Dispatch(component, ev);
      changed = true;
      while (!posted_.empty() && !quit_) {
        auto events = std::move(posted_);
        posted_.clear();
        for (auto& pe : events) Dispatch(component, pe);
      }
    }
    pending_.erase(0, pos);
    if (g_resized) {
      g_resized = 0;
      changed = true;
    }
    if (redraw_requested_) {
      redraw_requested_ = false;
      changed = true;
    }
    if (quit_) break;
    if (changed) Draw(component);
  }
  Uninstall();
  g_active = previous;
}

}  // namespace tui
