#include "date.hpp"

#include <ctime>
#include <vector>

namespace caps {

bool IsLeapYear(int y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }

int DaysInMonth(int y, int m) {
  static const int kDays[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  if (m == 2 && IsLeapYear(y)) return 29;
  return kDays[(m - 1) % 12];
}

long DaysFromCivil(int y, int m, int d) {
  y -= m <= 2;
  const long era = (y >= 0 ? y : y - 399) / 400;
  const unsigned yoe = static_cast<unsigned>(y - era * 400);
  const unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
  const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  return era * 146097 + static_cast<long>(doe) - 719468;
}

Date CivilFromDays(long z) {
  z += 719468;
  const long era = (z >= 0 ? z : z - 146096) / 146097;
  const unsigned doe = static_cast<unsigned>(z - era * 146097);
  const unsigned yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  const long y = static_cast<long>(yoe) + era * 400;
  const unsigned doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  const unsigned mp = (5 * doy + 2) / 153;
  const unsigned d = doy - (153 * mp + 2) / 5 + 1;
  const unsigned m = mp < 10 ? mp + 3 : mp - 9;
  Date out;
  out.year = static_cast<int>(y + (m <= 2));
  out.month = static_cast<int>(m);
  out.day = static_cast<int>(d);
  return out;
}

int WeekdayMonday0(const Date& d) {
  long z = DaysFromCivil(d.year, d.month, d.day);
  // 1970-01-01 was a Thursday (Monday0 index 3).
  long w = (z + 3) % 7;
  if (w < 0) w += 7;
  return static_cast<int>(w);
}

Date Today() {
  std::time_t t = std::time(nullptr);
  std::tm tmv{};
  localtime_r(&t, &tmv);
  Date d;
  d.year = tmv.tm_year + 1900;
  d.month = tmv.tm_mon + 1;
  d.day = tmv.tm_mday;
  return d;
}

std::string FormatDate(const Date& d, const std::string& fmt) {
  std::tm tmv{};
  tmv.tm_year = d.year - 1900;
  tmv.tm_mon = d.month - 1;
  tmv.tm_mday = d.day;
  if (fmt.empty()) return "";
  std::vector<char> buf(fmt.size() * 8 + 256);
  for (int attempt = 0; attempt < 6; ++attempt) {
    size_t n = std::strftime(buf.data(), buf.size(), fmt.c_str(), &tmv);
    if (n > 0 || buf.size() > 1 << 20) return std::string(buf.data(), n);
    buf.resize(buf.size() * 4);
  }
  return "";
}

}  // namespace caps
