namespace {

struct ParsedOpt {
  std::string key;  // as written (without dashes) or "-x" for short
  bool is_short = false;
  std::vector<std::string> values;
  std::string original;
};

// Find option for a token used as a key.
// Returns index or -1. Throws on ambiguity.
int FindOption(const std::vector<CliOptionDesc>& desc, const std::string& key,
               bool is_short, bool approx, const std::string& original,
               bool throw_ambiguous) {
  if (is_short) {
    for (size_t i = 0; i < desc.size(); ++i) {
      if (!desc[i].short_name.empty() && "-" + desc[i].short_name == key)
        return static_cast<int>(i);
    }
    return -1;
  }
  // full match first
  std::vector<int> approx_matches;
  for (size_t i = 0; i < desc.size(); ++i) {
    if (desc[i].long_name == key) return static_cast<int>(i);
    if (!desc[i].short_name.empty() && "-" + desc[i].short_name == key)
      return static_cast<int>(i);
  }
  if (approx) {
    for (size_t i = 0; i < desc.size(); ++i) {
      if (desc[i].long_name.find(key) == 0) approx_matches.push_back(int(i));
    }
  }
  if (approx_matches.size() == 1) return approx_matches[0];
  if (approx_matches.size() > 1) {
    if (!throw_ambiguous) return approx_matches[0];
    std::string alts;
    for (size_t i = 0; i < approx_matches.size(); ++i) {
      if (i > 0) {
        alts += (i + 1 == approx_matches.size()) ? ", and " : ", ";
      }
      alts += "'--" + desc[approx_matches[i]].long_name + "'";
    }
    (void)original;
    throw CliError("option '" + original + "' is ambiguous and matches " +
                   alts);
  }
  return -1;
}

std::string Canonical(const CliOptionDesc& d) {
  if (!d.long_name.empty()) return "--" + d.long_name;
  return "-" + d.short_name;
}

bool LooksLikeOption(const std::string& tok) {
  if (tok.size() >= 3 && tok[0] == '-' && tok[1] == '-') return true;
  if (tok.size() >= 2 && tok[0] == '-' && tok[1] != '-') return true;
  if (tok == "--") return true;
  return false;
}

}  // namespace

CliResult ParseCli(const std::vector<CliOptionDesc>& desc,
                   const std::vector<std::string>& input) {
  std::vector<std::string> args = input;
  struct Done {
    int index;
    std::string value;
  };
  std::vector<Done> done;

  auto finish = [&](ParsedOpt& opt, std::vector<std::string>& other) {
    if (opt.key.empty()) return;
    std::string orig = opt.original;
    int idx;
    // For unknown/ambiguous use original token.
    idx = FindOption(desc, opt.key, false, true, orig, true);
    if (idx < 0) throw CliError("unrecognised option '" + orig + "'");
    const auto& d = desc[idx];
    unsigned min_tokens = d.takes_value ? 1 : 0;
    unsigned max_tokens = d.takes_value ? 1 : 0;
    unsigned present = static_cast<unsigned>(opt.values.size() + other.size());
    if (present >= min_tokens) {
      if (!opt.values.empty() && max_tokens == 0) {
        throw CliError("option '" + Canonical(d) +
                       "' does not take any arguments");
      }
      if (opt.values.size() <= min_tokens) {
        min_tokens -= static_cast<unsigned>(opt.values.size());
      } else {
        min_tokens = 0;
      }
      while (!other.empty() && min_tokens--) {
        const std::string& next = other[0];
        if (LooksLikeOption(next) && next != "--") {
          // Only short names can match tokens with dashes.
          bool known = false;
          for (const auto& dd : desc) {
            if (!dd.short_name.empty() && "-" + dd.short_name == next) known = true;
          }
          if (known) {
            throw CliError("the required argument for option '" +
                           Canonical(d) + "' is missing");
          }
        } else if (next == "--") {
          // "--" is parsed by the terminator parser; as a value it's fine.
        }
        opt.values.push_back(next);
        other.erase(other.begin());
      }
    } else {
      throw CliError("the required argument for option '" + Canonical(d) +
                     "' is missing");
    }
    done.push_back({idx, opt.values.empty() ? "" : opt.values[0]});
  };

  while (!args.empty()) {
    const std::string tok = args[0];
    if (tok.size() >= 3 && tok[0] == '-' && tok[1] == '-') {
      ParsedOpt opt;
      auto p = tok.find('=');
      std::string name, adjacent;
      if (p != std::string::npos) {
        name = tok.substr(2, p - 2);
        adjacent = tok.substr(p + 1);
        if (adjacent.empty()) {
