  } else {
    par.erase(par_indent, 1);
    if (par_indent >= line_length) par_indent = 0;
  }
  if (par.size() < line_length) {
    os << par;
    return;
  }
  auto line_begin = par.cbegin();
  const auto par_end = par.cend();
  bool first_line = true;
  while (line_begin < par_end) {
    if (!first_line) {
      if ((*line_begin == ' ') &&
          ((line_begin + 1 < par_end) && (*(line_begin + 1) != ' '))) {
        line_begin += 1;
      }
    }
    unsigned remaining =
        static_cast<unsigned>(std::distance(line_begin, par_end));
    auto line_end =
        line_begin + ((remaining < line_length) ? remaining : line_length);
    if ((*(line_end - 1) != ' ') && ((line_end < par_end) && (*line_end != ' '))) {
      auto last_space = line_end;
      while (last_space != line_begin && *(last_space - 1) != ' ') --last_space;
      if (last_space != line_begin) {
        if (static_cast<unsigned>(std::distance(last_space, line_end)) <
            (line_length / 2)) {
          line_end = last_space;
        }
      }
    }
    os << std::string(line_begin, line_end);
    if (first_line) {
      indent += static_cast<unsigned>(par_indent);
      line_length -= static_cast<unsigned>(par_indent);
      first_line = false;
    }
    if (line_end != par_end) {
      os << '\n';
      for (unsigned pad = indent; pad > 0; --pad) os.put(' ');
    }
    line_begin = line_end;
  }
}

void FormatDescription(std::ostream& os, const std::string& desc,
                       unsigned first_column_width, unsigned line_length) {
  if (line_length > 1) --line_length;
