struct ParsedOpt {
  std::string key;  // as written (without dashes) or "-x" for short
  bool is_short = false;
  std::vector<std::string> values;
  std::string original;
};

// Find option for a token used as a key.
// Returns index or -1. Throws on ambiguity.
int FindOption(const std::vector<CliOptionDesc>& desc, const std::string& key,
               bool is_short, bool approx, const std::string& original,
               bool throw_ambiguous) {
  if (is_short) {
    for (size_t i = 0; i < desc.size(); ++i) {
      if (!desc[i].short_name.empty() && "-" + desc[i].short_name == key)
        return static_cast<int>(i);
    }
    return -1;
  }
  // full match first
  std::vector<int> approx_matches;
  for (size_t i = 0; i < desc.size(); ++i) {
    if (desc[i].long_name == key) return static_cast<int>(i);
    if (!desc[i].short_name.empty() && "-" + desc[i].short_name == key)
      return static_cast<int>(i);
  }
  if (approx) {
    for (size_t i = 0; i < desc.size(); ++i) {
      if (desc[i].long_name.find(key) == 0) approx_matches.push_back(int(i));
    }
  }
  if (approx_matches.size() == 1) return approx_matches[0];
  if (approx_matches.size() > 1) {
    if (!throw_ambiguous) return approx_matches[0];
    std::string alts;
    for (size_t i = 0; i < approx_matches.size(); ++i) {
      if (i > 0) {
        alts += (i + 1 == approx_matches.size()) ? ", and " : ", ";
      }
      alts += "'--" + desc[approx_matches[i]].long_name + "'";
    }
    (void)original;
    throw CliError("option '" + original + "' is ambiguous and matches " +
                   alts);
  }
  return -1;
}

std::string Canonical(const CliOptionDesc& d) {
  if (!d.long_name.empty()) return "--" + d.long_name;
  return "-" + d.short_name;
}

bool LooksLikeOption(const std::string& tok) {
  if (tok.size() >= 3 && tok[0] == '-' && tok[1] == '-') return true;
  if (tok.size() >= 2 && tok[0] == '-' && tok[1] != '-') return true;
  if (tok == "--") return true;
  return false;
}

