#include "ini.hpp"

#include <cctype>
#include <sstream>

namespace caps {

namespace {
std::string Trim(const std::string& s) {
  size_t b = 0, e = s.size();
  while (b < e && std::isspace(static_cast<unsigned char>(s[b]))) ++b;
  while (e > b && std::isspace(static_cast<unsigned char>(s[e - 1]))) --e;
  return s.substr(b, e - b);
}
std::string Err(unsigned long line, const std::string& msg) {
  return "<unspecified file>(" + std::to_string(line) + "): " + msg;
}
}  // namespace

Ini Ini::Parse(const std::string& content) {
  Ini ini;
  ini.sections_[""];
  std::istringstream stream(content);
  unsigned long line_no = 0;
  std::string line;
  std::string section;
  bool in_section = false;
  while (stream.good()) {
    ++line_no;
    std::getline(stream, line);
    line = Trim(line);
    if (line.empty()) continue;
    if (line[0] == ';' || line[0] == '#') continue;
    if (line[0] == '[') {
      if (in_section && ini.sections_[section].empty()) {
        ini.sections_.erase(section);
        ini.section_order_.pop_back();
      }
      auto end = line.find(']');
      if (end == std::string::npos) throw IniError(Err(line_no, "unmatched '['"));
      std::string key = Trim(line.substr(1, end - 1));
      bool dup = ini.sections_.count(key) && key != "";
      if (!dup) {
        for (auto& kv : ini.sections_[""]) {
          if (kv.first == key) dup = true;
        }
      }
      if (key.empty()) {
        // An empty section name collides with nothing at top level in practice.
        dup = false;
        for (auto& s : ini.section_order_) if (s.empty()) dup = true;
      }
      if (dup) throw IniError(Err(line_no, "duplicate section name"));
      section = key;
      in_section = true;
      ini.sections_[section];
      ini.section_order_.push_back(section);
      continue;
    }
    auto eqpos = line.find('=');
    if (eqpos == std::string::npos)
      throw IniError(Err(line_no, "'=' character not found in line"));
    if (eqpos == 0) throw IniError(Err(line_no, "key expected"));
    std::string key = Trim(line.substr(0, eqpos));
    std::string data = Trim(line.substr(eqpos + 1));
