inline uint8_t Xtime(uint8_t x) {
  return static_cast<uint8_t>((x << 1) ^ ((x & 0x80) ? 0x1b : 0));
}

struct Aes128 {
  uint8_t rk[176];
  explicit Aes128(const uint8_t key[16]) {
    std::memcpy(rk, key, 16);
    uint8_t rcon = 1;
    for (int i = 16; i < 176; i += 4) {
      uint8_t t[4] = {rk[i - 4], rk[i - 3], rk[i - 2], rk[i - 1]};
      if (i % 16 == 0) {
        uint8_t u = t[0];
        t[0] = kSbox[t[1]] ^ rcon;
        t[1] = kSbox[t[2]];
        t[2] = kSbox[t[3]];
        t[3] = kSbox[u];
        rcon = Xtime(rcon);
      }
      for (int j = 0; j < 4; ++j) rk[i + j] = rk[i - 16 + j] ^ t[j];
    }
  }
  void Encrypt(const uint8_t in[16], uint8_t out[16]) const {
    uint8_t s[16];
    for (int i = 0; i < 16; ++i) s[i] = in[i] ^ rk[i];
    for (int round = 1; round <= 10; ++round) {
      uint8_t t[16];
      // SubBytes + ShiftRows
      for (int c = 0; c < 4; ++c) {
        for (int r = 0; r < 4; ++r) {
          t[c * 4 + r] = kSbox[s[((c + r) % 4) * 4 + r]];
        }
      }
      if (round != 10) {
        for (int c = 0; c < 4; ++c) {
          uint8_t* col = t + c * 4;
          uint8_t a0 = col[0], a1 = col[1], a2 = col[2], a3 = col[3];
          uint8_t all = a0 ^ a1 ^ a2 ^ a3;
          col[0] = a0 ^ all ^ Xtime(a0 ^ a1);
          col[1] = a1 ^ all ^ Xtime(a1 ^ a2);
          col[2] = a2 ^ all ^ Xtime(a2 ^ a3);
          col[3] = a3 ^ all ^ Xtime(a3 ^ a0);
        }
      }
      for (int i = 0; i < 16; ++i) s[i] = t[i] ^ rk[round * 16 + i];
    }
    std::memcpy(out, s, 16);
  }
};

void DeriveKeyIv(const std::string& password, uint8_t key[16], uint8_t iv[16]) {
  std::string d1 = Md5(password);
  std::string d2 = Md5(d1 + password);
  std::memcpy(key, d1.data(), 16);
  std::memcpy(iv, d2.data(), 16);
}

std::string Cfb(const std::string& password, const std::string& in,
                bool encrypt) {
  uint8_t key[16], iv[16];
  DeriveKeyIv(password, key, iv);
  Aes128 aes(key);
  std::string out(in.size(), '\0');
  uint8_t reg[16];
  std::memcpy(reg, iv, 16);
  uint8_t ks[16];
  for (size_t off = 0; off < in.size(); off += 16) {
    aes.Encrypt(reg, ks);
    size_t n = std::min<size_t>(16, in.size() - off);
    for (size_t i = 0; i < n; ++i) {
      uint8_t c = static_cast<uint8_t>(in[off + i]) ^ ks[i];
      out[off + i] = static_cast<char>(c);
      reg[i] = encrypt ? c : static_cast<uint8_t>(in[off + i]);
    }
  }
  return out;
}
}  // namespace

std::string Md5(const std::string& data) {
  Md5Ctx ctx;
  std::string msg = data;
  uint64_t bitlen = static_cast<uint64_t>(data.size()) * 8;
  msg.push_back(static_cast<char>(0x80));
  while (msg.size() % 64 != 56) msg.push_back('\0');
  for (int i = 0; i < 8; ++i) msg.push_back(static_cast<char>((bitlen >> (8 * i)) & 0xff));
  for (size_t i = 0; i < msg.size(); i += 64) {
    Md5Block(ctx, reinterpret_cast<const unsigned char*>(msg.data() + i));
  }
  std::string out(16, '\0');
  uint32_t v[4] = {ctx.a, ctx.b, ctx.c, ctx.d};
  for (int i = 0; i < 4; ++i) {
    for (int j = 0; j < 4; ++j) out[i * 4 + j] = static_cast<char>((v[i] >> (8 * j)) & 0xff);
  }
  return out;
}

std::string EncryptCfb(const std::string& password, const std::string& plain) {
  return Cfb(password, plain, true);
}
std::string DecryptCfb(const std::string& password, const std::string& cipher) {
  return Cfb(password, cipher, false);
}

}  // namespace caps
