#include "repo.hpp"

#include <sys/stat.h>
#include <unistd.h>

#include <cctype>
#include <cstdio>
#include <fstream>
#include <sstream>

#include "crypto.hpp"

namespace caps {

const char* const kRootSection = "<root section>";

std::string ToLowerAscii(std::string s) {
  for (auto& c : s) {
    if (c >= 'A' && c <= 'Z') c = static_cast<char>(c - 'A' + 'a');
  }
  return s;
}

std::string TrimWs(const std::string& s) {
  size_t b = 0, e = s.size();
  while (b < e && std::isspace(static_cast<unsigned char>(s[b]))) ++b;
  while (e > b && std::isspace(static_cast<unsigned char>(s[e - 1]))) --e;
  return s.substr(b, e - b);
}

namespace {
bool IsWs(char c) { return std::isspace(static_cast<unsigned char>(c)) != 0; }

// "^\s*# (.*)" -> trimmed, non-empty.
std::optional<std::string> MatchSection(const std::string& line) {
  size_t i = 0;
  while (i < line.size() && IsWs(line[i])) ++i;
  if (i + 1 >= line.size()) return std::nullopt;
  if (line[i] != '#' || line[i + 1] != ' ') return std::nullopt;
  std::string rest = TrimWs(line.substr(i + 2));
  if (rest.empty()) return std::nullopt;
  return rest;
}

bool IsTagChar(char c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
         (c >= '0' && c <= '9') || c == ' ' || c == '-';
}

// ^\s*\* +([a-zA-Z0-9 -]+?)\s*(\(.+\))?(:.*)?\s*$
std::optional<std::string> MatchTag(const std::string& line) {
  size_t i = 0;
  while (i < line.size() && IsWs(line[i])) ++i;
  if (i >= line.size() || line[i] != '*') return std::nullopt;
  ++i;
  if (i >= line.size() || line[i] != ' ') return std::nullopt;
  while (i < line.size() && line[i] == ' ') ++i;
  size_t name_start = i;
  while (i < line.size() && IsTagChar(line[i])) ++i;
  size_t name_end = i;
  if (name_end == name_start) return std::nullopt;
  // remaining: \s*(\(.+\))?(:.*)?\s*$
  size_t j = i;
  while (j < line.size() && IsWs(line[j])) ++j;
  std::string rest = line.substr(j);
  auto tail_ok = [](const std::string& r) {
    // (:.*)?\s*$
    if (r.empty()) return true;
    if (r[0] == ':') return true;
    for (char c : r) {
      if (!IsWs(c)) return false;
    }
    return true;
  };
  bool ok = false;
  if (!rest.empty() && rest[0] == '(') {
    // greedy: find last ')' such that tail matches and content non-empty
    for (size_t k = rest.size(); k-- > 1;) {
      if (rest[k] == ')' && k >= 2) {
        if (tail_ok(rest.substr(k + 1))) {
          ok = true;
          break;
        }
      }
    }
    if (!ok) ok = tail_ok(rest);
  } else {
    ok = tail_ok(rest);
  }
  if (!ok) {
    // Name may also have consumed trailing spaces only; the whitespace
    // between name and the rest is covered above.
    return std::nullopt;
  }
  std::string name = line.substr(name_start, name_end - name_start);
  // trim trailing spaces (lazy match + \s*)
  while (!name.empty() && name.back() == ' ') name.pop_back();
  if (name.empty()) return std::nullopt;
  return ToLowerAscii(name);
}
}  // namespace

LogInfo ParseLog(const std::string& content, bool first_line_section) {
  LogInfo info;
  std::string current = kRootSection;
  bool in_root = true;
  std::istringstream in(content);
  std::string line;
  int idx = 0;
  while (std::getline(in, line)) {
    const bool first = idx == 0;
    ++idx;
    if (!(first && !first_line_section)) {
      if (auto s = MatchSection(line)) {
        current = ToLowerAscii(*s);
        in_root = false;
        info.sections[current];
        continue;
      }
    }
    if (auto t = MatchTag(line)) {
      info.sections[current].insert(*t);
    }
  }
  (void)in_root;
  return info;
}

bool ReadFile(const std::string& path, std::string* out) {
  std::ifstream f(path, std::ios::binary);
  if (!f.is_open()) return false;
  std::ostringstream ss;
  ss << f.rdbuf();
  *out = ss.str();
  return true;
}

bool WriteFile(const std::string& path, const std::string& content) {
  std::ofstream f(path, std::ios::binary | std::ios::trunc);
  if (!f.is_open()) return false;
  f << content;
  return static_cast<bool>(f);
}

bool FileExists(const std::string& path) {
  struct stat st {};
  return ::stat(path.c_str(), &st) == 0;
}

bool IsDirectory(const std::string& path) {
  struct stat st {};
  return ::stat(path.c_str(), &st) == 0 && S_ISDIR(st.st_mode);
}

std::string JoinPath(const std::string& a, const std::string& b) {
  if (a.empty()) return b;
  if (!b.empty() && b[0] == '/') return b;
  if (a.back() == '/') return a + b;
  return a + "/" + b;
}

std::string ParentPath(const std::string& p) {
  auto pos = p.find_last_of('/');
  if (pos == std::string::npos) return "";
  if (pos == 0) return "/";
  return p.substr(0, pos);
}

bool CreateDirectories(const std::string& p) {
  if (p.empty()) return true;
  if (IsDirectory(p)) return true;
  std::string parent = ParentPath(p);
  if (!parent.empty() && parent != p) CreateDirectories(parent);
  return ::mkdir(p.c_str(), 0755) == 0 || IsDirectory(p);
}

std::string Repository::PathFor(const Date& d) const {
  std::string year_dir = JoinPath(cfg_.log_dir, "y" + std::to_string(d.year));
  return JoinPath(year_dir, FormatDate(d, cfg_.name_format));
}

bool Repository::Exists(const Date& d) const { return FileExists(PathFor(d)); }

std::string Repository::Decode(const std::string& raw) const {
  if (cfg_.password) return DecryptCfb(*cfg_.password, raw);
  return raw;
}

std::string Repository::Encode(const std::string& plain) const {
  if (cfg_.password) return EncryptCfb(*cfg_.password, plain);
  return plain;
}

std::optional<std::string> Repository::Read(const Date& d) const {
  std::string raw;
  if (!ReadFile(PathFor(d), &raw)) return std::nullopt;
  return Decode(raw);
}

bool Repository::Write(const Date& d, const std::string& content) const {
  std::string p = PathFor(d);
  CreateDirectories(ParentPath(p));
  return WriteFile(p, Encode(content));
}

bool Repository::Remove(const Date& d) const {
  return ::unlink(PathFor(d).c_str()) == 0;
}

std::string Repository::ScratchpadDir() const {
  return JoinPath(cfg_.log_dir, "scratchpads");
}

}  // namespace caps
