      if (j != std::string::npos) {
        flush();
        out.push_back(text("`"));
        out.push_back(Styled(s.substr(i + 1, j - i - 1), st, true, theme));
        out.push_back(text("`"));
        i = j + 1;
        continue;
      }
      cur.push_back(c);
      ++i;
      continue;
    }
    if ((c == '*' || c == '_') && i + 1 < n && s[i + 1] == c) {
      flush();
      out.push_back(text(std::string(2, c)));
      st.bold = !st.bold;
      i += 2;
      continue;
    }
    if (c == '*' || c == '_') {
      flush();
      out.push_back(text(std::string(1, c)));
      st.italic = !st.italic;
      i += 1;
      continue;
    }
    if (c == '~' && i + 1 < n && s[i + 1] == '~') {
      flush();
      out.push_back(text("~~"));
      st.strike = !st.strike;
      i += 2;
      continue;
    }
    if (c == '[') {
      size_t close = s.find(']', i + 1);
      if (close != std::string::npos && close + 1 < n && s[close + 1] == '(') {
        size_t paren = s.find(')', close + 2);
        if (paren != std::string::npos) {
          flush();
          out.push_back(text("["));
          out.push_back(text(s.substr(i + 1, close - i - 1)) | underlined |
                        color(theme.link));
          out.push_back(text("]("));
          out.push_back(text(s.substr(close + 2, paren - close - 2)) |
                        underlined | color(theme.link));
          out.push_back(text(")"));
          i = paren + 1;
          continue;
        }
      }
      cur.push_back(c);
      ++i;
      continue;
    }
    cur.push_back(c);
    ++i;
  }
  flush();
  return out;
}

bool IsSpace(char c) { return c == ' ' || c == '\t'; }

bool IsHorizontalRule(const std::string& line) {
  char mark = 0;
  int count = 0;
  for (char c : line) {
    if (IsSpace(c)) continue;
    if (c != '-' && c != '*' && c != '_') return false;
    if (mark == 0) mark = c;
    if (c != mark) return false;
    ++count;
  }
  return count >= 3;
}

}  // namespace

Elements RenderMarkdown(const std::vector<std::string>& lines,
                        const MarkdownTheme& theme) {
  Elements out;
  bool in_fence = false;
  for (const auto& line : lines) {
    if (line.rfind("```", 0) == 0) {
      in_fence = !in_fence;
      out.push_back(text(line) | dim | color(theme.code_fg));
      continue;
    }
    if (in_fence) {
      out.push_back(text(line) | color(theme.code_fg));
      continue;
    }
    // Header
    if (!line.empty() && line[0] == '#') {
      size_t k = 0;
      while (k < line.size() && line[k] == '#') ++k;
      if (k < line.size() && line[k] == ' ') {
        int level = static_cast<int>(k);
        if (level > 6) level = 6;
        Element e = hbox(RenderInline(line, theme));
        e = color(theme.header[level - 1], e);
        if (level <= 2) e = bold(e);
        out.push_back(e);
        continue;
      }
    }
    if (IsHorizontalRule(line)) {
      out.push_back(text(line) | dim);
      continue;
    }
    // Quote
    if (!line.empty() && line[0] == '>') {
      size_t k = 0;
      while (k < line.size() && line[k] == '>') {
        ++k;
        if (k < line.size() && line[k] == ' ') ++k;
      }
      Elements parts;
      parts.push_back(text(line.substr(0, k)) | color(theme.quote));
      for (auto& e : RenderInline(line.substr(k), theme)) parts.push_back(e);
      out.push_back(hbox(std::move(parts)));
      continue;
    }
    // List
    {
      size_t k = 0;
      while (k < line.size() && IsSpace(line[k])) ++k;
      size_t m = k;
      bool is_list = false;
      if (m < line.size() && (line[m] == '*' || line[m] == '-' || line[m] == '+')) {
        if (m + 1 < line.size() && line[m + 1] == ' ') {
          is_list = true;
          m += 2;
        }
      } else if (m < line.size() && std::isdigit(static_cast<unsigned char>(line[m]))) {
        size_t d = m;
        while (d < line.size() && std::isdigit(static_cast<unsigned char>(line[d]))) ++d;
        if (d + 1 < line.size() && line[d] == '.' && line[d + 1] == ' ') {
          is_list = true;
          m = d + 2;
        }
      }
      if (is_list) {
        Elements parts;
        if (k > 0) parts.push_back(text(line.substr(0, k)));
        parts.push_back(text(line.substr(k, m - k)) | bold | color(theme.list));
        for (auto& e : RenderInline(line.substr(m), theme)) parts.push_back(e);
        out.push_back(hbox(std::move(parts)));
        continue;
      }
    }
    out.push_back(hbox(RenderInline(line, theme)));
  }
  return out;
}

}  // namespace caps
