                               "May",     "June",     "July",      "August",
                               "September", "October", "November", "December"};

std::string Pad3(int n) {
  char buf[32];
  std::snprintf(buf, sizeof(buf), "%3d", n);
  return buf;
}

int MonthsPerRow(int width) {
  if (width >= 6 * 34) return 6;
  if (width >= 4 * 34) return 4;
  if (width >= 3 * 34) return 3;
  if (width >= 2 * 34) return 2;
  return 1;
}

int TerminalWidth() {
  struct winsize_t {
    unsigned short r, c, x, y;
  };
  return 0;
}

