class App {
 public:
  explicit App(const AppConfig& cfg)
      : cfg_(cfg), repo_(cfg.repo), screen_(ScreenInteractive::Fullscreen()) {
    today_ = Today();
    cursor_ = today_;
    ResetMonthMemory();
    LoadYear();
  }

  int Run();

 private:
  // ---------------- data ----------------
  void ResetMonthMemory() {
    for (int m = 0; m < 12; ++m) month_mem_[m] = 1;
    month_mem_[cursor_.month - 1] = cursor_.day;
  }

  void LoadYear() {
    logs_.clear();
    const int y = cursor_.year;
    for (int m = 1; m <= 12; ++m) {
      for (int d = 1; d <= DaysInMonth(y, m); ++d) {
        Date dt{y, m, d};
        std::string path = repo_.PathFor(dt);
        if (!FileExists(path)) continue;
        std::string raw;
        LogInfo info;
        if (ReadFile(path, &raw)) {
          info = ParseLog(repo_.Decode(raw), cfg_.first_line_section);
        }
        logs_[dt] = info;
      }
    }
    RebuildSections();
  }

  void RebuildSections() {
    std::map<std::string, int> counts;
    for (const auto& kv : logs_) {
      for (const auto& s : kv.second.sections) {
        if (s.first == kRootSection && s.second.empty()) continue;
        counts[s.first]++;
      }
    }
    std::string previous;
    if (section_sel_ > 0 && section_sel_ < int(section_names_.size()))
      previous = section_names_[section_sel_];
    section_names_.clear();
    section_labels_.clear();
    section_names_.push_back("");
    section_labels_.push_back("<select none>");
    for (const auto& kv : counts) {
      section_names_.push_back(kv.first);
      section_labels_.push_back(Pad3(kv.second) + " │ " + kv.first);
    }
    int sel = 0;
    if (!previous.empty()) {
      for (size_t i = 0; i < section_names_.size(); ++i) {
        if (section_names_[i] == previous) sel = static_cast<int>(i);
      }
    }
    section_sel_ = sel;
    RebuildTags();
  }

  void RebuildTags() {
    std::map<std::string, int> counts;
    const std::string sec = section_names_[section_sel_];
    for (const auto& kv : logs_) {
      std::set<std::string> tags;
      for (const auto& s : kv.second.sections) {
        if (!sec.empty() && s.first != sec) continue;
        for (const auto& t : s.second) tags.insert(t);
      }
      for (const auto& t : tags) counts[t]++;
    }
    std::string previous;
    if (tag_sel_ > 0 && tag_sel_ < int(tag_names_.size()))
      previous = tag_names_[tag_sel_];
    tag_names_.clear();
    tag_labels_.clear();
    tag_names_.push_back("");
    tag_labels_.push_back("<select none>");
    for (const auto& kv : counts) {
      tag_names_.push_back(kv.first);
      tag_labels_.push_back(Pad3(kv.second) + " │ " + kv.first);
    }
    int sel = 0;
    if (!previous.empty()) {
      for (size_t i = 0; i < tag_names_.size(); ++i) {
        if (tag_names_[i] == previous) sel = static_cast<int>(i);
      }
    }
    tag_sel_ = sel;
    RebuildHighlights();
  }

  void RebuildHighlights() {
    highlighted_.clear();
    const std::string sec = section_names_[section_sel_];
    const std::string tag = tag_names_[tag_sel_];
    if (sec.empty() && tag.empty()) return;
    for (const auto& kv : logs_) {
      bool hit = false;
      for (const auto& s : kv.second.sections) {
        if (!sec.empty() && s.first != sec) continue;
        if (tag.empty()) {
          hit = true;
        } else if (s.second.count(tag)) {
          hit = true;
        }
      }
      if (hit) highlighted_.insert(kv.first);
    }
  }

  // ---------------- rendering ----------------
  Element RenderMenu(const std::vector<std::string>& labels, int selected,
                     bool focused) {
    Elements elements;
    for (int i = 0; i < int(labels.size()); ++i) {
      const bool is_selected = i == selected;
      const bool is_focused = is_selected && focused;
      Element e = text((is_selected ? "> " : "  ") + labels[i]);
      if (is_focused) e = inverted(e);
      if (is_selected) e = bold(e);
      if (is_selected) e = focused ? focus(e) : select(e);
      elements.push_back(e);
    }
    return vbox(std::move(elements));
  }

  Element MenuWindow(const std::string& title, const std::vector<std::string>& labels,
                     int selected, bool focused, BorderStyle style) {
    Element inner = RenderMenu(labels, selected, focused);
    inner = vscroll_indicator(inner);
    inner = frame(inner);
    inner = inner | size(HEIGHT, EQUAL, 18) | size(WIDTH, EQUAL, 23);
    Element w = window(text(title), inner, style);
    if (!focused) w = dim(w);
    return w;
  }

  Element RenderDay(const Date& d, bool calendar_focused) {
    const Theme& th = cfg_.theme;
    std::string num = std::to_string(d.day);
    Element e = text(num);
    const bool has_log = logs_.count(d) > 0;
    const bool is_today = d == today_;
    const bool is_cursor = d == cursor_;
    const int wd = WeekdayMonday0(d);
    const bool weekend = wd >= 5;
    bool is_event = false;
    for (const auto& ev : cfg_.events) {
      if (ev.month == d.month && ev.day == d.day) is_event = true;
    }
    const bool is_high = highlighted_.count(d) > 0;
    if (is_cursor && calendar_focused) e = inverted(e);
    if (is_today) e = th.todays_date.Apply(e);
    if (is_high) e = th.highlighted_date.Apply(e);
    if (weekend) e = th.weekend_date.Apply(e);
    if (is_event) e = th.event_date.Apply(e);
    if (has_log) {
      e = th.log_date.Apply(e);
    } else if (calendar_focused) {
      e = th.empty_date.Apply(e);
    }
    (void)is_cursor;
    return e;
  }

  Element RenderMonth(int month, bool calendar_focused) {
    const int y = cursor_.year;
    std::vector<Elements> grid;
    // header
    {
      Elements hdr;
      const char* mon[7] = {" M ", " T ", " W ", " T ", " F ", " S ", " S "};
      const char* sun[7] = {" S ", " M ", " T ", " W ", " T ", " F ", " S "};
      for (int i = 0; i < 7; ++i) {
        hdr.push_back(text(cfg_.sunday_start ? sun[i] : mon[i]) | underlined);
      }
      grid.push_back(hdr);
    }
    const int first_wd = WeekdayMonday0(Date{y, month, 1});
    const int offset = cfg_.sunday_start ? (first_wd + 1) % 7 : first_wd;
    Elements row;
    if (offset == 0) {
      grid.push_back(Elements{});
    }
    for (int i = 0; i < offset; ++i) row.push_back(text("   "));
    const int days = DaysInMonth(y, month);
    for (int d = 1; d <= days; ++d) {
      if (row.size() == 7) {
        grid.push_back(row);
        row.clear();
      }
      Date dt{y, month, d};
      Element num = hbox({text(d < 10 ? " " : ""), RenderDay(dt, calendar_focused)});
      bool mark = (month == cursor_.month) && (grid.size() == 2) && row.empty();
      if (mark) num = calendar_focused ? focus(num) : select(num);
      row.push_back(hbox({num, text(" ")}));
    }
    if (!row.empty()) grid.push_back(row);
    return window(text(kMonthNames[month - 1]), gridbox(grid),
                  cfg_.theme.calendar_month_border);
  }

  Element RenderCalendar(bool focused, int width) {
    const int mpr = MonthsPerRow(width);
    Elements rows;
    Elements current;
    for (int m = 1; m <= 12; ++m) {
      current.push_back(RenderMonth(m, focused));
      if (int(current.size()) == mpr) {
