        current.clear();
      }
    }
    if (!current.empty()) rows.push_back(hbox(current));
    Element content = frame(vbox(rows));
    Element w = window(text(std::to_string(cursor_.year)), content,
                       cfg_.theme.calendar_border);
    w = vscroll_indicator(w);
    if (!focused) w = dim(w);
    return w;
  }

  Element RenderEvents() {
    Elements lines;
