  AppConfig cfg_;
  Repository repo_;
  ScreenInteractive& screen_;
  Date today_;
  Date cursor_;
  int month_mem_[12];
  std::map<Date, LogInfo> logs_;
  std::vector<std::string> section_names_, section_labels_;
  std::vector<std::string> tag_names_, tag_labels_;
  int section_sel_ = 0;
  int tag_sel_ = 0;
  std::set<Date> highlighted_;
  int focus_ = 0;
  int preview_offset_ = 0;
  bool delete_dialog_ = false;
  int delete_button_ = 0;
};

bool App::OnCalendarEvent(const Event& e) {
  const int dim = DaysInMonth(cursor_.year, cursor_.month);
  Date d = cursor_;
  auto prev_month = [&]() {
    if (cursor_.month == 1) return;
    Date n{cursor_.year, cursor_.month - 1, month_mem_[cursor_.month - 2]};
    MoveCursor(n);
  };
  auto next_month = [&]() {
    if (cursor_.month == 12) return;
    Date n{cursor_.year, cursor_.month + 1, month_mem_[cursor_.month]};
    MoveCursor(n);
  };
  if (e == Event::ArrowLeft || e == Event::Character('h')) {
    if (d.day > 1) {
      d.day--;
      MoveCursor(d);
    } else {
      prev_month();
    }
    return true;
  }
  if (e == Event::ArrowRight || e == Event::Character('l')) {
    if (d.day < dim) {
      d.day++;
      MoveCursor(d);
    } else {
      next_month();
    }
    return true;
  }
  if (e == Event::ArrowUp || e == Event::Character('k')) {
    if (d.day - 7 >= 1) {
      d.day -= 7;
      MoveCursor(d);
    } else {
      prev_month();
    }
    return true;
  }
  if (e == Event::ArrowDown || e == Event::Character('j')) {
    if (d.day + 7 <= dim) {
      d.day += 7;
      MoveCursor(d);
    } else {
      next_month();
    }
    return true;
  }
  return false;
}

void App::OpenEditor() {
  const std::string path = repo_.PathFor(cursor_);
  const std::string initial = FormatDate(cursor_, "# %d. %m. %y.");
  bool created = false;
  if (!FileExists(path)) {
    CreateDirectories(ParentPath(path));
    WriteFile(path, repo_.Encode(initial));
    created = true;
  }
  const char* ed = std::getenv("EDITOR");
  std::string editor = ed ? ed : "";
  screen_.WithRestoredIO([&]() {
    std::string cmd = editor + " " + path;
    int rc = std::system(cmd.c_str());
    (void)rc;
  });
  std::string after;
  if (ReadFile(path, &after)) {
    if (repo_.Decode(after) == initial || after.empty()) {
      if (created || repo_.Decode(after) == initial) ::unlink(path.c_str());
    }
  }
  LoadYear();
}

bool App::OnEvent(Event e) {
  if (delete_dialog_) {
    if (e == Event::ArrowLeft || e == Event::Character('h')) {
      delete_button_ = 0;
      return true;
    }
    if (e == Event::ArrowRight || e == Event::Character('l')) {
      delete_button_ = 1;
      return true;
    }
    if (e == Event::Tab) {
      delete_button_ = (delete_button_ + 1) % 2;
      return true;
    }
    if (e == Event::TabReverse) {
      delete_button_ = (delete_button_ + 1) % 2;
      return true;
    }
    if (e == Event::Return) {
      if (delete_button_ == 0) {
        repo_.Remove(cursor_);
        LoadYear();
      }
      delete_dialog_ = false;
      return true;
    }
    return false;
  }
  if (e == Event::Character('q') || e == Event::Escape) {
    screen_.Exit();
    return true;
  }
  if (e == Event::Tab) {
    focus_ = (focus_ + 1) % 4;
    return true;
  }
  if (e == Event::TabReverse) {
    focus_ = (focus_ + 3) % 4;
    return true;
  }
  if (e == Event::Character('+')) {
    ChangeYear(1);
    return true;
  }
  if (e == Event::Character('-')) {
    ChangeYear(-1);
    return true;
  }
  if (focus_ == 0 || focus_ == 1) {
    auto& sel = focus_ == 0 ? section_sel_ : tag_sel_;
    const int n = focus_ == 0 ? int(section_labels_.size()) : int(tag_labels_.size());
    int old = sel;
    if (e == Event::ArrowUp || e == Event::Character('k')) sel--;
    if (e == Event::ArrowDown || e == Event::Character('j')) sel++;
    if (e == Event::Home) sel = 0;
    if (e == Event::End) sel = n - 1;
    sel = std::max(0, std::min(n - 1, sel));
    if (sel != old) {
      if (focus_ == 0) {
        tag_sel_ = 0;
        RebuildTags();
      } else {
        RebuildHighlights();
      }
      return true;
    }
    return false;
  }
  if (focus_ == 2) {
    if (e == Event::Return) {
      OpenEditor();
      return true;
    }
    if (e == Event::Character('d')) {
      if (logs_.count(cursor_)) {
        delete_dialog_ = true;
        delete_button_ = 0;
      }
      return true;
    }
    return OnCalendarEvent(e);
  }
  if (focus_ == 3) {
    auto content = repo_.Read(cursor_);
    int n = content ? int(SplitLines(*content).size()) : 0;
    if (e == Event::ArrowUp || e == Event::Character('k')) {
      if (preview_offset_ > 0) preview_offset_--;
      return true;
    }
    if (e == Event::ArrowDown || e == Event::Character('j')) {
      if (preview_offset_ < n - 1) preview_offset_++;
      return true;
    }
  }
  return false;
}

int App::Run() {
  auto root = Renderer([this]() {
    int w = ScreenInteractive::Fullscreen().dimx();
    if (w <= 0) w = 80;
    Element doc = RenderAnnual(w);
    if (delete_dialog_) {
      Element yes = text("Yes") | borderLight;
      Element no = text("No") | borderLight;
      if (delete_button_ == 0) yes = focus(inverted(yes)); else no = focus(inverted(no));
      Element dialog = border(vbox({
          text("Are you sure you want to delete a log file?"),
          separator(),
          hcenter(hbox({yes, no})),
      }));
      doc = dbox({doc | dim | color(Color::GrayDark), center(clear_under(dialog))});
    }
    return doc;
  });
  auto catcher = CatchEvent(root, [this](Event e) { return OnEvent(e); });
  screen_.Loop(catcher);
  return 0;
}

int RunApp(const AppConfig& config) {
  App app(config);
  return app.Run();
}

