std::string ExpandHome(const std::string& p, const std::string& home) {
  if (!p.empty() && p[0] == '~') return home + p.substr(1);
  return p;
}

// boost::property_tree style bool translation: "1"/"0" or "true"/"false".
std::optional<bool> ParseBool(const std::string& s) {
  if (s == "1") return true;
  if (s == "0") return false;
  if (s == "true") return true;
  if (s == "false") return false;
  return std::nullopt;
}

bool GetBool(const Ini& ini, const std::string& section, const std::string& key,
             bool def) {
  auto v = ini.Get(section, key);
  if (!v) return def;
  auto b = ParseBool(*v);
  return b ? *b : def;
}

std::optional<unsigned long> ParseUnsigned32(const std::string& in) {
  std::string s = TrimWs(in);
  if (s.empty()) return std::nullopt;
  size_t i = 0;
  bool neg = false;
  if (s[i] == '+' || s[i] == '-') {
    neg = s[i] == '-';
    ++i;
  }
  if (i >= s.size()) return std::nullopt;
  unsigned long long v = 0;
  for (; i < s.size(); ++i) {
    if (s[i] < '0' || s[i] > '9') return std::nullopt;
    v = v * 10 + (s[i] - '0');
    if (v > 0xFFFFFFFFull) return std::nullopt;
  }
  if (neg) v = (0x100000000ull - v) & 0xFFFFFFFFull;
  return static_cast<unsigned long>(v);
}

std::vector<std::string> SplitDots(const std::string& s) {
  std::vector<std::string> out;
  std::string cur;
  for (char c : s) {
    if (c == '.') {
      out.push_back(cur);
      cur.clear();
    } else {
      cur.push_back(c);
    }
  }
  out.push_back(cur);
  return out;
}

struct ColorParseError : std::runtime_error {
  using std::runtime_error::runtime_error;
};

int StoiLike(const std::string& tok) {
  // std::stoi semantics: optional whitespace, sign, digits; rest ignored.
  const char* p = tok.c_str();
  char* end = nullptr;
  errno = 0;
  long v = std::strtol(p, &end, 10);
  if (end == p) throw ColorParseError("Invalid numeric value in color: " + tok);
  if (errno == ERANGE || v < INT_MIN || v > INT_MAX)
    throw ColorParseError("Invalid numeric value in color: " + tok);
  return static_cast<int>(v);
}

std::vector<std::string> SplitArgs(const std::string& s) {
  std::vector<std::string> out;
  std::string cur;
  auto push = [&]() {
    std::string t = TrimWs(cur);
    if (!t.empty()) out.push_back(t);
    cur.clear();
  };
  for (char c : s) {
    if (c == ',') {
      push();
    } else {
      cur.push_back(c);
    }
  }
  push();
  return out;
}

const char* kAnsiNames[16] = {
    "black",       "red",         "green",        "yellow",
    "blue",        "magenta",     "cyan",         "white",
    "brightblack", "brightred",   "brightgreen",  "brightyellow",
    "brightblue",  "brightmagenta", "brightcyan", "brightwhite"};

Color ParseColorOrThrow(const std::string& value) {
  const std::string s = TrimWs(value);
  const std::string l = ToLowerAscii(s);
  if (l == "default") return Color();
  if (!s.empty() && s[0] == '#') {
    if (s.size() != 7) throw ColorParseError("Invalid hex color format: " + s);
    int v[3];
    for (int i = 0; i < 3; ++i) {
      int x = 0;
      for (int j = 0; j < 2; ++j) {
        char c = s[1 + 2 * i + j];
        int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else throw ColorParseError("Invalid hex color value: " + s);
        x = x * 16 + d;
      }
      v[i] = x;
    }
    return Color::Rgb(v[0], v[1], v[2]);
  }
  auto open = s.find('(');
  if (open == std::string::npos || s.size() < 2 || s.back() != ')' ||
      open + 2 > s.size() - 1) {
    throw ColorParseError("Invalid color format: " + s);
  }
  const std::string name = ToLowerAscii(s.substr(0, open));
  const std::string args = s.substr(open + 1, s.size() - open - 2);
  if (args.empty()) throw ColorParseError("Invalid color format: " + s);
  if (name == "rgb" || name == "rgba") {
    auto toks = SplitArgs(args);
    const bool rgba = name == "rgba";
    if (!rgba && toks.size() != 3)
      throw ColorParseError("RGB color expects 3 values: " + s);
    if (rgba && toks.size() != 4)
      throw ColorParseError("RGBA color expects 4 values: " + s);
    int v[4] = {0, 0, 0, 0};
    for (size_t i = 0; i < toks.size(); ++i) v[i] = StoiLike(toks[i]);
    for (int i = 0; i < 3; ++i) {
      if (v[i] < 0 || v[i] > 255)
        throw ColorParseError(std::string(rgba ? "RGBA" : "RGB") +
                              " values out of range: " + s);
    }
    if (rgba && (v[3] < 0 || v[3] > 255))
      throw ColorParseError("RGBA alpha out of range: " + s);
    return Color::Rgb(v[0], v[1], v[2]);
  }
  if (name == "ansi16") {
    auto toks = SplitArgs(args);
    if (toks.size() != 1) throw ColorParseError("ansi16 expects 1 value: " + s);
    const std::string& t = toks[0];
    bool numeric = !t.empty();
    for (char c : t) {
      if (c < '0' || c > '9') numeric = false;
    }
    if (numeric) {
      int v = StoiLike(t);
      if (v < 0 || v > 15) throw ColorParseError("ansi16 value out of range: " + t);
      return Color::Index16(v);
    }
    std::string ln = ToLowerAscii(t);
    for (int i = 0; i < 16; ++i) {
      if (ln == kAnsiNames[i]) return Color::Index16(i);
    }
    throw ColorParseError("Unknown ansi16 color name: " + t);
  }
  if (name == "ansi256") {
    auto toks = SplitArgs(args);
    if (toks.size() != 1) throw ColorParseError("ansi256 expects 1 value: " + s);
    int v = StoiLike(toks[0]);
    if (v < 0 || v > 255) throw ColorParseError("ansi256 value out of range: " + s);
    return Color::Index256(v);
  }
  throw ColorParseError("Unknown color format: " + s);
}

TextStyle ParseStyle(const Ini& ini, const std::string& section) {
  TextStyle st;
  for (const char* key : {"fgcolor", "bgcolor"}) {
    auto v = ini.Get(section, key);
    if (!v || TrimWs(*v).empty()) continue;
    try {
      Color c = ParseColorOrThrow(*v);
      if (std::string(key) == "fgcolor") st.fg = c; else st.bg = c;
    } catch (const ColorParseError& e) {
      throw ConfigError("Invalid " + section + "." + key + " (" + *v + "): " + e.what());
    }
  }
  st.bold = GetBool(ini, section, "bold", false);
  st.italic = GetBool(ini, section, "italic", false);
  st.underlined = GetBool(ini, section, "underlined", false);
  st.dim = GetBool(ini, section, "dim", false);
  st.inverted = GetBool(ini, section, "inverted", false);
  st.strikethrough = GetBool(ini, section, "strikethrough", false);
  st.blink = GetBool(ini, section, "blink", false);
  return st;
}

BorderStyle ParseBorderOrThrow(const std::string& v, const std::string& where) {
  std::string l = ToLowerAscii(TrimWs(v));
  if (l == "light") return LIGHT;
  if (l == "dashed") return DASHED;
  if (l == "heavy") return HEAVY;
  if (l == "double") return DOUBLE;
  if (l == "rounded") return ROUNDED;
  if (l == "empty") return EMPTY;
  throw ConfigError("Invalid border style for " + where + ": " + v);
}

void MaybeBorder(const Ini& ini, const std::string& section, const std::string& key,
                 BorderStyle* out) {
  auto v = ini.Get(section, key);
  if (!v) return;
  *out = ParseBorderOrThrow(*v, section + "/" + key);
}

void ParseMarkdownTheme(const Ini& ini, const std::string& section, MarkdownTheme* t) {
  auto get = [&](const char* key, Color* out) {
    auto v = ini.Get(section, key);
    if (!v || TrimWs(*v).empty()) return;
    try {
      *out = ParseColorOrThrow(*v);
    } catch (const ColorParseError& e) {
      throw ConfigError("Invalid " + section + "." + key + " (" + *v + "): " + e.what());
    }
  };
  get("header1", &t->header[0]);
  get("header2", &t->header[1]);
  get("header3", &t->header[2]);
  get("header4", &t->header[3]);
  get("header5", &t->header[4]);
  get("header6", &t->header[5]);
  get("list", &t->list);
  get("quote", &t->quote);
  get("code-fg", &t->code_fg);
}

void ParseTheme(const Ini& ini, Theme* th) {
  const std::string base = "view.annual-view.theme";
  struct S {
    const char* name;
    TextStyle* style;
  } styles[] = {
      {"log-date", &th->log_date},         {"empty-date", &th->empty_date},
      {"highlighted-date", &th->highlighted_date},
      {"weekend-date", &th->weekend_date}, {"event-date", &th->event_date},
      {"todays-date", &th->todays_date},
  };
  for (auto& s : styles) {
    const std::string sec = base + "." + s.name;
    if (ini.HasSection(sec)) *s.style = ParseStyle(ini, sec);
  }
  MaybeBorder(ini, base, "calendar-border", &th->calendar_border);
  MaybeBorder(ini, base, "calendar-month-border", &th->calendar_month_border);
  MaybeBorder(ini, base, "tags-menu.border", &th->tags_menu_border);
  MaybeBorder(ini, base, "sections-menu.border", &th->sections_menu_border);
  MaybeBorder(ini, base, "events-list.border", &th->events_list_border);
  MaybeBorder(ini, base, "log-entry-preview.border", &th->log_entry_preview_border);
  MaybeBorder(ini, base + ".tags-menu", "border", &th->tags_menu_border);
  MaybeBorder(ini, base + ".sections-menu", "border", &th->sections_menu_border);
  MaybeBorder(ini, base + ".events-list", "border", &th->events_list_border);
  MaybeBorder(ini, base + ".log-entry-preview", "border", &th->log_entry_preview_border);
  ParseMarkdownTheme(ini, base + ".log-entry-preview.markdown-theme", &th->preview_md);

  const std::string sbase = "view.scratchpad-view.theme";
  MaybeBorder(ini, sbase, "menu.border", &th->scratchpad_menu_border);
  MaybeBorder(ini, sbase, "preview.border", &th->scratchpad_preview_border);
  MaybeBorder(ini, sbase + ".menu", "border", &th->scratchpad_menu_border);
  MaybeBorder(ini, sbase + ".preview", "border", &th->scratchpad_preview_border);
  ParseMarkdownTheme(ini, sbase + ".preview.markdown-theme", &th->scratchpad_md);
}

void ParseEvents(const Ini& ini, AppConfig* cfg) {
  if (auto v = ini.Get("calendar-events", "recent-events-window")) {
    if (auto u = ParseUnsigned32(*v)) cfg->recent_events_window = *u;
  }
  const std::string prefix = "calendar-events.";
  for (const auto& sec : ini.Sections()) {
    if (sec.rfind(prefix, 0) != 0) continue;
    auto parts = SplitDots(sec);
    if (parts.size() != 3) throw ConfigError("Invalid calendar event key: " + sec);
    auto name = ini.Get(sec, "name");
    if (!name) throw ConfigError("No such node (name)");
    auto date = ini.Get(sec, "date");
    if (!date) throw ConfigError("No such node (date)");
    unsigned char d = 0, m = 0;
    if (std::sscanf(date->c_str(), "%2hhu.%2hhu", &d, &m) != 2) {
      throw ConfigError("Invalid date format: " + *date);
    }
    CalendarEvent ev;
    ev.group = parts[1];
    ev.name = *name;
    ev.day = d;
    ev.month = m;
    cfg->events.push_back(ev);
  }
}

bool IsParentPath(const std::string& parent, const std::string& child) {
  // lexical comparison of path components
  auto comps = [](const std::string& p) {
    std::vector<std::string> out;
    std::string cur;
    for (char c : p) {
      if (c == '/') {
        if (!cur.empty()) out.push_back(cur);
        cur.clear();
      } else {
        cur.push_back(c);
      }
    }
    if (!cur.empty()) out.push_back(cur);
    return out;
  };
  auto a = comps(parent);
  auto b = comps(child);
  if (a.size() > b.size()) return false;
  for (size_t i = 0; i < a.size(); ++i) {
    if (a[i] != b[i]) return false;
  }
  return true;
}

void ParseGit(const Ini& ini, const AppConfig& cfg, const std::string& home,
              GitConfig* git) {
  git->enabled = GetBool(ini, "git", "enable-git-log-repo", false);
  if (!git->enabled) return;
  git->ssh_key_path = ExpandHome(ini.Get("git", "ssh-key-path").value_or(""), home);
  git->ssh_pub_key_path = ExpandHome(ini.Get("git", "ssh-pub-key-path").value_or(""), home);
  git->repo_root = ExpandHome(ini.Get("git", "repo-root").value_or(""), home);
  if (auto v = ini.Get("git", "remote-name")) git->remote_name = *v;
  if (auto v = ini.Get("git", "main-branch-name")) git->main_branch_name = *v;
  if (git->ssh_key_path.empty()) throw ConfigError("SSH key path can not be empty!");
  if (git->ssh_pub_key_path.empty())
    throw ConfigError("SSH public key path can not be empty!");
  if (git->repo_root.empty()) throw ConfigError("Git repository root can not be empty!");
  if (!IsParentPath(git->repo_root, cfg.repo.log_dir)) {
    throw ConfigError("Error! Git repo root (" + git->repo_root +
                      ") is not parent of log dir (" + cfg.repo.log_dir + ")!");
  }
  if (!FileExists(git->ssh_key_path))
    throw ConfigError("SSH key does not exist: " + git->ssh_key_path);
  if (!FileExists(git->ssh_pub_key_path))
    throw ConfigError("SSH public key does not exist: " + git->ssh_pub_key_path);
  if (!FileExists(git->repo_root))
    throw ConfigError("Git repository root does not exist: " + git->repo_root);
}

}  // namespace

void LoadAppConfig(const Ini& ini, const CliResult& cli, const std::string& home,
                   AppConfig* cfg, GitConfig* git) {
  cfg->repo.log_dir = home + "/.caps-log/day/";
  cfg->repo.name_format = "d%Y_%m_%d.md";
  if (auto v = ini.Get("", "log-dir-path")) cfg->repo.log_dir = ExpandHome(*v, home);
  if (auto v = ini.Get("", "log-filename-format")) cfg->repo.name_format = *v;
  cfg->sunday_start = GetBool(ini, "", "sunday-start", false);
  cfg->first_line_section = GetBool(ini, "", "first-line-section", false);
  if (auto v = ini.Get("", "password")) cfg->repo.password = *v;
  if (auto v = cli.get("log-dir-path")) cfg->repo.log_dir = *v;
  if (auto v = cli.get("log-name-format")) cfg->repo.name_format = *v;
  if (cli.has("sunday-start")) cfg->sunday_start = true;
  if (cli.has("first-line-section")) cfg->first_line_section = true;
  if (auto v = cli.get("password")) cfg->repo.password = *v;
  cfg->theme = DefaultTheme();
  ParseTheme(ini, &cfg->theme);
  ParseEvents(ini, cfg);
  ParseGit(ini, *cfg, home, git);
}

