void App::OpenScratchpadEditor(const std::string& name) {
  const char* ed = std::getenv("EDITOR");
  if (!ed) return;
  const std::string path = JoinPath(repo_.ScratchpadDir(), name);
  std::string editor = ed;
  if (cfg_.repo.password) {
    std::string raw;
    const bool existed = ReadFile(path, &raw);
    std::string tmp = TempEditPath();
    if (existed) WriteFile(tmp, repo_.Decode(raw));
    screen_.WithRestoredIO([&]() {
      std::string cmd = editor + " " + tmp;
      int rc = std::system(cmd.c_str());
      (void)rc;
    });
    std::string after;
    if (ReadFile(tmp, &after)) {
      WriteFile(path, repo_.Encode(after));
      ::unlink(tmp.c_str());
    }
    return;
  }
  screen_.WithRestoredIO([&]() {
    std::string cmd = editor + " " + path;
    int rc = std::system(cmd.c_str());
    (void)rc;
  });
}

