    return true;
  }
  if (sp_dialog_ == SpDialog::New || sp_dialog_ == SpDialog::Rename) {
    if (e == Event::Tab || e == Event::TabReverse) {
      sp_input_focus_ = 1 - sp_input_focus_;
      return true;
    }
    if (sp_input_focus_ == 0) {
      if (e == Event::ArrowRight && sp_input_.empty()) {
        sp_input_focus_ = 1;
        return true;
      }
    } else {
      if (e == Event::ArrowLeft || e == Event::Character('h')) {
        sp_input_focus_ = 0;
        return true;
      }
    }
    bool submit = false;
    if (e == Event::Return) {
      submit = true;
    } else if (sp_input_focus_ == 0) {
      if (e == Event::Backspace) {
        if (!sp_input_.empty()) {
          size_t p = sp_input_.size() - 1;
          while (p > 0 && (static_cast<unsigned char>(sp_input_[p]) & 0xC0) == 0x80) --p;
          sp_input_.erase(p);
        }
        return true;
      }
      if (e.is_character()) {
        sp_input_ += e.character();
        return true;
      }
    }
    if (submit) {
      std::string name = sp_input_;
      if (name.size() < 3 || name.compare(name.size() - 3, 3, ".md") != 0) name += ".md";
      const SpDialog kind = sp_dialog_;
      sp_dialog_ = SpDialog::None;
      if (kind == SpDialog::New) {
        OpenScratchpadEditor(name);
      } else {
        const std::string dir = repo_.ScratchpadDir();
        std::rename(JoinPath(dir, SelectedScratchpad()).c_str(), JoinPath(dir, name).c_str());
      }
      ResetScratchpadView();
    }
    return true;
  }
  if (e == Event::Character('q') || e == Event::Escape) {
    screen_.Exit();
    return true;
  }
  if (e == Event::F1) {
    help_open_ = true;
    return true;
  }
  if (e == Event::Character('s')) {
    scratchpad_mode_ = false;
    return true;
  }
  if (sp_focus_ == 0) {
    if (e == Event::Return) {
      const char* ed = std::getenv("EDITOR");
      if (!ed) return true;
      if (sp_menu_.selected == 0) {
        sp_dialog_ = SpDialog::New;
        sp_input_.clear();
        sp_input_focus_ = 0;
      } else {
        OpenScratchpadEditor(SelectedScratchpad());
        ResetScratchpadView();
      }
      return true;
    }
    if (e == Event::Character('d') && sp_menu_.selected > 0) {
      sp_dialog_ = SpDialog::Delete;
      sp_delete_button_ = 0;
      return true;
    }
    if (e == Event::Character('r') && sp_menu_.selected > 0) {
      sp_dialog_ = SpDialog::Rename;
      sp_input_.clear();
      sp_input_focus_ = 0;
      return true;
    }
    sp_menu_.size = static_cast<int>(sp_labels_.size());
    const int old = sp_menu_.selected;
    bool handled = sp_menu_.OnEvent(e);
    if (!handled && (e == Event::Tab || e == Event::TabReverse) && sp_menu_.size > 0) {
      if (e == Event::Tab) sp_menu_.selected = (sp_menu_.selected + 1) % sp_menu_.size;
      else sp_menu_.selected = (sp_menu_.selected + sp_menu_.size - 1) % sp_menu_.size;
      handled = sp_menu_.selected != old;
    }
    if (handled) {
      sp_selection_changed_ = true;
      sp_preview_offset_ = 0;
      return true;
    }
    if (e == Event::ArrowRight || e == Event::Character('l')) {
      sp_focus_ = 1;
      return true;
    }
    return false;
  }
  // preview focused
  if (e == Event::ArrowUp || e == Event::Character('k')) {
    if (sp_preview_offset_ > 0) sp_preview_offset_--;
    return true;
  }
  if (e == Event::ArrowDown || e == Event::Character('j')) {
    std::string raw;
    int n = 0;
    if (ReadFile(JoinPath(repo_.ScratchpadDir(), SelectedScratchpad()), &raw))
      n = static_cast<int>(SplitLines(repo_.Decode(raw)).size());
    if (sp_preview_offset_ < n - 1) sp_preview_offset_++;
    return true;
  }
  if (e == Event::ArrowLeft || e == Event::Character('h') || e == Event::Tab ||
      e == Event::TabReverse) {
    sp_focus_ = 0;
    return true;
  }
  return false;
}

void App::OpenScratchpadEditor(const std::string& name) {
  const char* ed = std::getenv("EDITOR");
  if (!ed) return;
  const std::string path = JoinPath(repo_.ScratchpadDir(), name);
  std::string editor = ed;
  if (cfg_.repo.password) {
    std::string raw;
    const bool existed = ReadFile(path, &raw);
    std::string tmp = TempEditPath();
    if (existed) WriteFile(tmp, repo_.Decode(raw));
    screen_.WithRestoredIO([&]() {
      std::string cmd = editor + " " + tmp;
      int rc = std::system(cmd.c_str());
      (void)rc;
    });
    std::string after;
    if (ReadFile(tmp, &after)) {
      WriteFile(path, repo_.Encode(after));
      ::unlink(tmp.c_str());
    }
    return;
  }
  screen_.WithRestoredIO([&]() {
    std::string cmd = editor + " " + path;
    int rc = std::system(cmd.c_str());
    (void)rc;
  });
}

