#include "crypto_repo.hpp"

#include <ctime>
#include <filesystem>
#include <iomanip>
#include <sstream>
#include <stdexcept>
#include <vector>

#include "crypto.hpp"

namespace caps {

namespace fs = std::filesystem;

const char* const kEncryptionMarker = "encryption-marker:";

bool CheckPassword(const std::string& log_dir, const std::string& password) {
  std::string raw;
  if (!ReadFile(JoinPath(log_dir, ".cle"), &raw)) return false;
  return DecryptCfb(password, raw) == kEncryptionMarker;
}

namespace {

bool IsYearDir(const std::string& name) {
  if (name.size() != 5 || name[0] != 'y') return false;
  for (size_t i = 1; i < 5; ++i) {
    if (name[i] < '0' || name[i] > '9') return false;
  }
  return true;
}

bool MatchesFormat(const std::string& name, const std::string& format) {
  std::tm tmv{};
  std::istringstream ss(name);
  ss >> std::get_time(&tmv, format.c_str());
  return !ss.fail() && ss.eof();
}

void Process(const fs::path& p, const std::string& password, bool encrypt) {
  std::string raw;
  if (!ReadFile(p.string(), &raw)) return;
  std::string out = encrypt ? EncryptCfb(password, raw) : DecryptCfb(password, raw);
  WriteFile(p.string(), out);
}

}  // namespace

void ApplyCrypto(const RepoConfig& cfg, bool encrypt) {
  const fs::path dir(cfg.log_dir);
  const fs::path marker = dir / ".cle";
  const bool applied = fs::exists(marker);
  if (encrypt == applied) throw std::runtime_error("Already applied");
  const std::string& password = *cfg.password;
  std::vector<fs::path> files;
  for (const auto& entry : fs::directory_iterator(dir)) {
    const std::string name = entry.path().filename().string();
    if (entry.is_directory() && IsYearDir(name)) {
      for (const auto& f : fs::directory_iterator(entry.path())) {
        if (!f.is_regular_file()) continue;
        if (MatchesFormat(f.path().filename().string(), cfg.name_format)) {
          files.push_back(f.path());
        }
      }
    } else if (entry.is_directory() && name == "scratchpads") {
      for (const auto& f : fs::directory_iterator(entry.path())) {
        if (!f.is_regular_file()) continue;
        if (f.path().extension() == ".md") files.push_back(f.path());
      }
    }
  }
  for (const auto& f : files) Process(f, password, encrypt);
  if (encrypt) {
    WriteFile(marker.string(), EncryptCfb(password, kEncryptionMarker));
  } else {
    fs::remove(marker);
  }
}

}  // namespace caps
