#include "git.hpp"

#include <fcntl.h>
#include <sys/wait.h>
#include <unistd.h>

#include <cstring>

namespace caps {

GitResult RunGit(const std::string& root, const std::vector<std::string>& args) {
  GitResult res;
  int fds[2];
  if (pipe(fds) != 0) return res;
  pid_t pid = fork();
  if (pid < 0) {
    close(fds[0]);
    close(fds[1]);
    return res;
  }
  if (pid == 0) {
    int devnull = open("/dev/null", O_RDONLY);
    if (devnull >= 0) dup2(devnull, STDIN_FILENO);
    dup2(fds[1], STDOUT_FILENO);
    dup2(fds[1], STDERR_FILENO);
    close(fds[0]);
    close(fds[1]);
    setenv("GIT_TERMINAL_PROMPT", "0", 1);
    std::vector<std::string> all = {"git", "-C", root};
    for (const auto& a : args) all.push_back(a);
    std::vector<char*> argv;
    for (auto& a : all) argv.push_back(const_cast<char*>(a.c_str()));
    argv.push_back(nullptr);
    execvp("git", argv.data());
    _exit(127);
  }
  close(fds[1]);
  char buf[4096];
  ssize_t n;
  while ((n = read(fds[0], buf, sizeof(buf))) > 0) res.output.append(buf, n);
  close(fds[0]);
  int status = 0;
  waitpid(pid, &status, 0);
  res.rc = WIFEXITED(status) ? WEXITSTATUS(status) : -1;
  return res;
}

bool GitIsRepo(const std::string& root) {
  return RunGit(root, {"rev-parse", "--git-dir"}).rc == 0;
}

bool GitHasRemote(const std::string& root, const std::string& remote) {
  GitResult r = RunGit(root, {"remote"});
  if (r.rc != 0) return false;
  size_t start = 0;
  while (start <= r.output.size()) {
    size_t end = r.output.find('\n', start);
    if (end == std::string::npos) end = r.output.size();
    if (r.output.substr(start, end - start) == remote) return true;
    start = end + 1;
  }
  return false;
}

std::string GitPull(const std::string& root, const std::string& remote,
                    const std::string& branch) {
  if (!GitHasRemote(root, remote)) {
    return "Error pulling from remote:Git error @/workspace/source/utils/git_repo.cpp:213remote '" +
           remote + "' does not exist";
  }
  GitResult f = RunGit(root, {"fetch", remote});
  if (f.rc != 0) {
    std::string out = f.output;
    while (!out.empty() && (out.back() == '\n' || out.back() == '\r')) out.pop_back();
    return "Error pulling from remote:" + out;
  }
  RunGit(root, {"merge", "--ff-only", remote + "/" + branch});
  return "";
}

void GitCommitAndPush(const std::string& root, const std::string& remote,
                      const std::string& branch) {
  RunGit(root, {"add", "-A"});
  if (RunGit(root, {"diff", "--cached", "--quiet"}).rc != 0) {
    RunGit(root, {"commit", "-m", "caps-log auto push"});
  }
  RunGit(root, {"push", remote, "HEAD:" + branch});
}

}  // namespace caps
